        v_ch1_id,
        $lesson$📌 পাঠ ১: হিসাববিজ্ঞানের সহজ ধারণা, উৎপত্তি ও লুকা প্যাসিওলির ইতিহাস

হিসাববিজ্ঞানকে বলা হয় **"ব্যবসায়ের ভাষা (Language of Business)"**। একটি প্রতিষ্ঠানে প্রতিদিন কী পরিমাণ পণ্য কেনাবেচা হলো, কত টাকা লাভ বা ক্ষতি হলো এবং বছর শেষে মোট কত সম্পদ ও দায় অবশিষ্ট রইল—তা জানার একমাত্র বিজ্ঞানসম্মত মাধ্যম হলো হিসাববিজ্ঞান।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. হিসাববিজ্ঞান কী?
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
হিসাববিজ্ঞান হলো এমন একটি তথ্য ব্যবস্থা (Information System), যা কোনো ব্যক্তি বা প্রতিষ্ঠানের যাবতীয় আর্থিক লেনদেনসমূহকে সুনির্দিষ্ট নিয়ম মেনে **লিপিবদ্ধকরণ, শ্রেণিবদ্ধকরণ, সংক্ষিপ্তকরণ** এবং ফলাফল বিশ্লেষণ করে সংশ্লিষ্ট তথ্য ব্যবহারকারীদের নিকট সরবরাহ করে।

• এ ডব্লিউ জনসন (A. W. Johnson)-এর মতে: "হিসাববিজ্ঞান হলো ব্যবসায়ের আর্থিক ঘটনাসমূহ সংগ্রহ, সংকলন ও বিশ্লেষণের একটি প্রক্রিয়া।"
• হিসাববিজ্ঞানের তিনটি মূল কাজ:
  ১. আর্থিক লেনদেন শনাক্তকরণ (Identification)
  ২. লেনদেন লিপিবদ্ধকরণ ও প্রক্রিয়াকরণ (Recording & Processing)
  ৩. ফলাফল ও তথ্য পরিবেশন (Communication / Reporting)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. হিসাববিজ্ঞানের উৎপত্তি ও ঐতিহাসিক ক্রমবিকাশ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
আদিম যুগে মানুষ যখন বনে-জঙ্গলে বাস করত, তখন তারা গাছের গায়ে দাগ কেটে বা গুহার দেয়ালে চিহ্ন এঁকে হিসাব রাখত। পরবর্তীকালে সমাজ ও বাণিজ্যের প্রসারের সাথে সাথে হিসাববিজ্ঞানের আধুনিক রূপ আবির্ভূত হয়।

────────────────────────────
■ লুকা প্যাসিওলি (Luca Pacioli) — হিসাববিজ্ঞানের জনক:
────────────────────────────
• **১৪৯৪ সালে** ইতালির ভেনিস শহরে প্রখ্যাত ধর্মযাজক ও গণিতবিদ **লুকা প্যাসিওলি (Fra Luca Bartolomeo de Pacioli)** তাঁর যুগান্তকারী গ্রন্থ রচনা করেন।
• বইটির নাম: **"Summa de Arithmetica, Geometria, Proportioni et Proportionalita"**
• এই গ্রন্থে তিনি সর্বপ্রথম **"দুতরফা দাখিলা পদ্ধতি (Double Entry System)"**-এর মূলনীতি ও বৈজ্ঞানিক নিয়মাবলী লিপিবদ্ধ করেন।
• এজন্য লুকা প্যাসিওলিকে সারা বিশ্বে **হিসাববিজ্ঞানের জনক** বলা হয়।$lesson$,
        1
    );

    -- ============================================================
    -- LESSON 2: হিসাববিজ্ঞানের মূল উদ্দেশ্য ও প্রয়োজনীয়তা
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch1_id,
        $lesson$📌 পাঠ ২: হিসাববিজ্ঞানের মূল উদ্দেশ্য ও প্রয়োজনীয়তা

হিসাববিজ্ঞান কেবল ব্যবসায়ের মুনাফা বের করার জন্যই ব্যবহৃত হয় না; বরং যে কোনো ব্যক্তি, পরিবার, অমুনাফায়িত স্কুল-কলেজ এবং সরকারের সার্বিক আর্থিক শৃঙ্খলা বজায় রাখার জন্য হিসাববিজ্ঞান অপরিহার্য।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. হিসাববিজ্ঞানের প্রধান ও মুখ্য উদ্দেশ্যসমূহ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. **আর্থিক লেনদেনসমূহ সুনির্দিষ্ট ও স্থায়ীভাবে লিপিবদ্ধ করা:** ব্যবসায়ের প্রতিদিনের অসংখ্য লেনদেন স্মৃতির ওপর নির্ভর না করে তারিখ অনুযায়ী হিসাবের প্রাথমিক ও পাকা বইয়ে লিখে রাখা।
২. **আর্থিক ফলাফল (লাভ বা ক্ষতি) নির্ণয়:** নির্দিষ্ট হিসাবকাল শেষে ব্যবসায়ের মোট আয় থেকে মোট ব্যয় বাদ দিয়ে নিট মুনাফা বা নিট ক্ষতি নিরূপণ করা।
৩. **আর্থিক অবস্থা (সম্পদ ও দায়) নিরূপণ:** বছর শেষে প্রতিষ্ঠানের মোট কত টাকার সম্পদ রয়েছে এবং বাইরের পক্ষের নিকট কত দায় রয়েছে তা উদ্বৃত্তপত্রের মাধ্যমে সুস্পষ্টভাবে জানা।
৪. **ব্যয় নিয়ন্ত্রণ (Cost Control):** কারবারের অপ্রয়োজনীয় ও অপচয়মূলক খরচ চিহ্নিত করে তা হ্রাস করা, যা ব্যবসায়ের মুনাফা বৃদ্ধিতে সরাসরি সাহায্য করে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. হিসাববিজ্ঞানের বাস্তব প্রয়োজনীয়তা:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• **প্রতারণা ও জালিয়াতি রোধ:** নিয়মিত হিসাব পরীক্ষা ও অভ্যন্তরীণ নিরীক্ষার মাধ্যমে তহবিল তছরুপ, চুরি ও দুর্নীতি প্রতিরোধ করা সম্ভব।
• **সঠিক সিদ্ধান্ত গ্রহণ:** প্রতিষ্ঠানের ভবিষ্যৎ সম্প্রসারণ, নতুন পণ্য উৎপাদন বা ঋণ গ্রহণের বিষয়ে নির্ভরযোগ্য আর্থিক তথ্যের ভিত্তিতে সঠিক সিদ্ধান্ত নেওয়া যায়।
• **কর ও ভ্যাট নির্ধারণ:** সরকারের সঠিক আয়কর, মূল্য সংযোজন কর (ভ্যাট) ও শুল্ক নির্ধারণের জন্য নির্ভুল হিসাব বই আইনগতভাবে বাধ্যতামূলক।
• **তুলনামূলক বিশ্লেষণ:** চলতি বছরের আর্থিক ফলাফলের সাথে বিগত বছরগুলোর ফলাফলের তুলনা করে ব্যবসায়ের অগ্রগতি ও দুর্বলতা চিহ্নিত করা যায়।$lesson$,
        2
    );

    -- ============================================================
    -- LESSON 3: হিসাব তথ্যের ব্যবহারকারী (অভ্যন্তরীণ বনাম বাহ্যিক)
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch1_id,
        $lesson$📌 পাঠ ৩: হিসাব তথ্যের ব্যবহারকারী (অভ্যন্তরীণ বনাম বাহ্যিক ব্যবহারকারী)

হিসাববিজ্ঞানকে একটি **"তথ্য ব্যবস্থা (Information System)"** হিসেবে গণ্য করা হয়। কারণ এটি আর্থিক প্রতিবেদন তৈরি করে তা বিভিন্ন পক্ষের নিকট পৌঁছায়। এই পক্ষগুলোকে প্রধানত **২টি শ্রেণিতে** ভাগ করা হয়:

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. অভ্যন্তরীণ ব্যবহারকারী (Internal Users):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
যারা প্রতিষ্ঠানের অভ্যন্তরে সরাসরি নীতি নির্ধারণ, ব্যবস্থাপনা ও দৈনন্দিন পরিচালনায় জড়িত থাকেন:
১. **মালিক (Owner):** ব্যবসায়ে তার বিনিয়োগকৃত মূলধনের নিরাপত্তা, মুনাফার হার এবং ব্যবসায়ের প্রবৃদ্ধি জানার জন্য।
২. **ব্যবস্থাপক বা পরিচালনা কর্তৃপক্ষ (Managers / Executives):** দৈনন্দিন কারবার পরিচালনা, খরচ নিয়ন্ত্রণ, মূল্য নির্ধারণ এবং ভবিষ্যৎ বাজেট প্রণয়নের জন্য।
৩. **অভ্যন্তরীণ নিরীক্ষক (Internal Auditor):** হিসাবের নির্ভুলতা ও কোম্পানির নিয়মকানুন যথাযথ মানা হচ্ছে কিনা তা যাচাইয়ের জন্য।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. বাহ্যিক ব্যবহারকারী (External Users):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
যারা প্রতিষ্ঠানের বাইরে অবস্থান করেন কিন্তু প্রতিষ্ঠানের সাথে প্রত্যক্ষ বা পরোক্ষ আর্থিক স্বার্থে জড়িত:
১. **ঋণদানকারী ও ব্যাংক (Lenders & Banks):** ঋণ দেওয়ার আগে প্রতিষ্ঠানটি যথাসময়ে সুদে-আসলে ঋণ পরিশোধে সক্ষম কিনা (তারল্য ও সচ্ছলতা) তা যাচাই করতে।
২. **পাওনাদার ও সরবরাহকারী (Creditors & Suppliers):** ধারে পণ্য বিক্রয় করার আগে ক্রেতার দেনা পরিশোধের আর্থিক সামর্থ্য নিশ্চিত হতে।
৩. **সরকার ও জাতীয় রাজস্ব বোর্ড (Government & NBR):** জাতীয় অর্থনীতির অগ্রগতি পরিমাপ এবং সঠিক আয়কর, ভ্যাট ও শুল্ক আদায়ের জন্য।
৪. **ভবিষ্যৎ বিনিয়োগকারী (Potential Investors):** কোম্পানিতে শেয়ার বা অর্থ বিনিয়োগ লাভজনক ও নিরাপদ হবে কিনা তা বিবেচনা করতে।
৫. **কর্মকর্তা ও কর্মচারী (Employees):** প্রতিষ্ঠানের আর্থিক সচ্ছলতার ওপর তাদের বেতন বৃদ্ধি, পদোন্নতি ও বোনাস নির্ভর করে।
৬. **গবেষক ও ভোক্তা অধিকার সংস্থা:** সামগ্রিক শিল্প খাতের উন্নয়ন গবেষণা ও ভোক্তার স্বার্থ সংরক্ষণের জন্য।

────────────────────────────
■ দ্রুত মনে রাখার তুলনামূলক ছক:
────────────────────────────
| তুলনার ক্ষেত্র | অভ্যন্তরীণ ব্যবহারকারী (Internal) | বাহ্যিক ব্যবহারকারী (External) |
| :--- | :--- | :--- |
| **সরাসরি পরিচালনা** | হ্যাঁ, সরাসরি ব্যবস্থাপনায় যুক্ত | না, বাইরে থেকে পর্যবেক্ষণ করেন |
| **প্রধান উদাহরণ** | মালিক, পরিচালক, বিভাগীয় ম্যানেজার | ব্যাংক, পাওনাদার, এনবিআর, বিনিয়োগকারী |
| **তথ্যের ধরন** | বিস্তারিত অভ্যন্তরীণ রিপোর্ট ও খসড়া | চূড়ান্ত নিরীক্ষিত আর্থিক বিবরণী |$lesson$,
        3
    );

    -- ============================================================
    -- LESSON 4: সমাজ, মূল্যবোধ ও জবাবদিহিতা সৃষ্টিতে হিসাববিজ্ঞান
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch1_id,
        $lesson$📌 পাঠ ৪: সমাজ, মূল্যবোধ ও জবাবদিহিতা সৃষ্টিতে হিসাববিজ্ঞানের ভূমিকা

হিসাববিজ্ঞান কেবল সংখ্যার খেলা বা ব্যবসায়ের লাভ-ক্ষতির হিসাব নয়; ব্যক্তি ও সমাজের সার্বিক নৈতিক মানদণ্ড উন্নয়নে হিসাববিজ্ঞান এক অনন্য ভূমিকা পালন করে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. মূল্যবোধ (Values) সৃষ্টিতে হিসাববিজ্ঞান:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
মূল্যবোধ হলো মানুষের আচার-আচরণ ও চিন্তাভাবনাকে পরিচালনাকারী অভ্যন্তরীণ নৈতিক অনুভূতি:
• **সততা ও বিশ্বস্ততা বৃদ্ধি:** প্রতিটি আর্থিক লেনদেনের সত্যতা যাচাই ও ভাউচার সংরক্ষণের বাধ্যবাধকতা থাকার কারণে আর্থিক জালিয়াতি করার সুযোগ থাকে না।
• **ঋণ পরিশোধে সচেতনতা:** হিসাবের খাতা নিয়মিত দেখলে কার দেনা কখন পরিশোধ করতে হবে তা সুস্পষ্ট থাকে, ফলে দেউলিয়া হওয়া এড়ানো যায়।
• **অপচয় রোধ:** হিসাববিজ্ঞানের বাজেট পদ্ধতির মাধ্যমে পরিবারের কিংবা ব্যবসায়ের অর্থের অপচয় ও অনর্থক বিলাসিতা কঠোরভাবে রোধ করা যায়।
• **ধর্মীয় ও নৈতিক অনুশাসন পালন:** ইসলাম ধর্মে যাকাত প্রদান বা অন্যান্য ধর্মে দান-খয়রাত সঠিকভাবে হিসাব করে আদায় করার জন্য হিসাববিজ্ঞান জরুরি।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. জবাবদিহিতা (Accountability) সৃষ্টিতে হিসাববিজ্ঞান:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
জবাবদিহিতা মানে হলো নিজের দায়িত্ব ও কর্মকাণ্ডের জন্য ঊর্ধ্বতন কর্তৃপক্ষ কিংবা সমাজের কাছে ব্যাখ্যা প্রদানে বাধ্য থাকা:
১. **মালিকের নিকট কর্মকর্তাদের জবাবদিহিতা:** নির্বাহীরা কোম্পানির অর্থ কীভাবে ব্যয় করেছেন তা বার্ষিক সাধারণ সভায় (AGM) আর্থিক প্রতিবেদনের মাধ্যমে মালিকদের নিকট উপস্থাপন করতে হয়।
২. **সরকারের নিকট প্রতিষ্ঠানের জবাবদিহিতা:** আইন অনুযায়ী প্রতি অর্থবছর শেষে সঠিক অডিট রিপোর্ট জমা দিয়ে কর ফাঁকি না দিয়ে রাষ্ট্রীয় কোষাগারে কর জমা দিতে হয়।
৩. **পরিবেশ ও সমাজের প্রতি দায়বদ্ধতা (CSR):** শিল্প কারখানার বর্জ্য ব্যবস্থাপনা, পরিবেশ দূষণ রোধ ও সামাজিক কল্যাণে ব্যয়িত তহবিলের সঠিক হিসাব রাখা।$lesson$,
        4
    );

    -- ============================================================
    -- LESSON 5: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch1_id,
        $lesson$📌 পাঠ ৫: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২ (পূর্ণাঙ্গ সমাধান)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০১ (সবচেয়ে গুরুত্বপূর্ণ - হিসাব তথ্যের ব্যবহারকারী)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব জামিল একজন পাইকারি কাপড় ব্যবসায়ী। ২০২৩ সালে তিনি তার ব্যবসা থেকে ৩০,০০,০০০ টাকা পণ্য বিক্রয় করে ৫,০০,০০০ টাকা মুনাফা অর্জন করেন। তিনি ব্যবসায়ের সম্প্রসারণের জন্য সোনালী ব্যাংকে ১০,০০,০০০ টাকা ঋণের আবেদন করেন। ব্যাংক কর্তৃপক্ষ তার ব্যবসায়ের বিগত ৩ বছরের আর্থিক বিবরণী পর্যালোচনা করে ঋণ মঞ্জুর করে। এদিকে জাতীয় রাজস্ব বোর্ড (NBR) তার অডিট রিপোর্ট দেখে বার্ষিক আয়কর ধার্য করে।

[করণীয় প্রশ্ন]:
ক) হিসাববিজ্ঞানের জনক কে এবং তিনি কোন দেশের অধিবাসী ছিলেন?
খ) উদ্দীপকে উল্লেখিত 'সোনালী ব্যাংক' এবং 'জাতীয় রাজস্ব বোর্ড (NBR)' হিসাব তথ্যের কোন শ্রেণির ব্যবহারকারী? ব্যাখ্যা কর।
গ) জনাব জামিলের ব্যবসায়ের ক্ষেত্রে হিসাব তথ্যের অভ্যন্তরীণ ব্যবহারকারী কারা এবং কেন তাদের এ তথ্যের প্রয়োজন হয়?

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) হিসাববিজ্ঞানের জনক ও তাঁর দেশ:**
হিসাববিজ্ঞানের জনক হলেন ইতালির বিখ্যাত গণিতবিদ ও ধর্মযাজক **লুকা প্যাসিওলি (Luca Pacioli)**। তিনি ইতালির ভেনিস শহরের অধিবাসী ছিলেন।

**খ) সোনালী ব্যাংক ও জাতীয় রাজস্ব বোর্ডের শ্রেণির ব্যাখ্যা:**
উদ্দীপকে উল্লেখিত 'সোনালী ব্যাংক' এবং 'জাতীয় রাজস্ব বোর্ড (NBR)' উভয়ই হিসাব তথ্যের **বাহ্যিক ব্যবহারকারী (External Users)**।
• **সোনালী ব্যাংক:** ব্যাংক ঋণ মঞ্জুর করার পূর্বে প্রতিষ্ঠানটির ঋণ পরিশোধের আর্থিক সামর্থ্য, তারল্য এবং মুনাফা অর্জনের ধারাবাহিকতা যাচাই করার জন্য আর্থিক বিবরণী পর্যালোচনা করেছে।
• **জাতীয় রাজস্ব বোর্ড:** সরকার ও এনবিআরের দায়িত্ব হলো আইনের আলোকে সঠিক কর নির্ধারণ করা। জামিল সাহেবের অর্জিত ৫,০০,০০০ টাকা মুনাফার ওপর ন্যাংয আয়কর নিরূপণের জন্য তারা এ তথ্যের ব্যবহারকারী হিসেবে গণ্য।

**গ) অভ্যন্তরীণ ব্যবহারকারী ও তাঁদের প্রয়োজনীয়তা:**
জনাব জামিলের ব্যবসায়ের অভ্যন্তরীণ ব্যবহারকারী হলেন:
১. **জনাব জামিল নিজে (মালিক):** কারণ ব্যবসায়ের সামগ্রিক লাভ-ক্ষতি, মূলধনের বৃদ্ধি এবং ভবিষ্যৎ বিনিয়োগ সুরক্ষার জন্য তাঁর এই তথ্যের প্রত্যক্ষ প্রয়োজন।
২. **দোকানের ম্যানেজার বা পরিচালনাকারী:** দৈনন্দিন বিক্রয় বাড়ানো, পণ্য মজুদের খরচ নিয়ন্ত্রণ এবং কর্মচারীদের নিয়মিত বেতন-ভাতা প্রদানের পরিকল্পনা সাজাতে তাঁদের এই তথ্য দরকার।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০২ (হিসাববিজ্ঞানের উদ্দেশ্য ও জবাবদিহিতা)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
'আভা এন্টারপ্রাইজ' প্রতিবছর নিয়মিত দুতরফা দাখিলা পদ্ধতিতে হিসাবরক্ষণ করে। বছর শেষে তারা কর্মচারীদের জন্য ৫% লভ্যাংশ ঘোষণা করে, নিয়মিত কর পরিশোধ করে এবং স্থানীয় বিদ্যালয়ের শিক্ষার্থীদের জন্য বিনামূল্যে খাতা-কলম বিতরণে একটি সামাজিক কল্যাণ তহবিল পরিচালনা করে।

[করণীয় প্রশ্ন]:
ক) লুকা প্যাসিওলির বিখ্যাত বইটি কত সালে প্রকাশিত হয়েছিল?
খ) আভা এন্টারপ্রাইজের নিয়মিত হিসাব সংরক্ষণের ২টি প্রধান উদ্দেশ্য আলোচনা কর।
গ) প্রতিষ্ঠানটির কর্মকাণ্ড কীভাবে সমাজ ও রাষ্ট্রীয় জবাবদিহিতা নিশ্চিত করছে? মূল্যায়ন কর।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) বই প্রকাশের সাল:**
লুকা প্যাসিওলির বিখ্যাত গ্রন্থ "Summa de Arithmetica..." প্রকাশিত হয়েছিল **১৪৯৪ সালে**।

**খ) আভা এন্টারপ্রাইজের হিসাব সংরক্ষণের ২টি প্রধান উদ্দেশ্য:**
১. **সঠিক আর্থিক ফলাফল নিরূপণ:** প্রতিষ্ঠানটির মোট বিক্রয় ও অন্যান্য আয় থেকে যাবতীয় পরিচালন ব্যয় বাদ দিয়ে নিট মুনাফা সুনির্দিষ্টভাবে জানা।
২. **আর্থিক অবস্থা পরিমাপ:** বছর শেষে প্রতিষ্ঠানের দেনাদার, নগদ তহবিল, আসবাবপত্র ও প্রদেয় পাওনার পরিমাণ স্পষ্ট করা।

**গ) সমাজ ও রাষ্ট্রীয় জবাবদিহিতা নিশ্চিতকরণ:**
প্রতিষ্ঠানটি হিসাববিজ্ঞানের মাধ্যমে সমাজ ও রাষ্ট্রের প্রতি চমৎকার জবাবদিহিতা তৈরি করেছে:
১. **রাষ্ট্রীয় জবাবদিহিতা:** নিয়মিত নির্ভুল হিসাবের মাধ্যমে কর ফাঁকি না দিয়ে সরকারকে যথাসময়ে ন্যায্য ট্যাক্স পরিশোধ করছে।
২. **কর্মীদের অধিকার রক্ষা:** অর্জিত মুনাফার সঠিক হিসাব থাকার ফলেই কর্মচারীদের ৫% লভ্যাংশ নিশ্চিত করা সম্ভব হয়েছে।
৩. **সামাজিক দায়বদ্ধতা (CSR):** স্থানীয় বিদ্যালয়ের সুবিধাবঞ্চিত শিক্ষার্থীদের শিক্ষা উপকরণ সরবরাহের জন্য আলাদা তহবিল গঠন করে তারা সামাজিকভাবে একটি আদর্শ প্রতিষ্ঠান হিসেবে প্রতিষ্ঠিত হয়েছে।$lesson$,
        5
    );

