    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch1_id,
        $lesson$📌 পাঠ ৬: সৃজনশীল প্রশ্ন ০৩, ০৪, ০৫ ও ফাইনাল ৫টি গোল্ডেন টিপস

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৩ (হিসাব তথ্যের বিভ্রান্তিকর ব্যবহারকারী চিহ্নিতকরণ)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
নিচের ব্যক্তি ও প্রতিষ্ঠানসমূহ কোনো না কোনোভাবে একটি কোম্পানির আর্থিক তথ্যের সাথে যুক্ত:
১. কোম্পানির ব্যবস্থাপনা পরিচালক (Managing Director)
২. অগ্রণী ব্যাংক পিএলসি (ঋণদাতা)
৩. কোম্পানির প্রধান হিসাবরক্ষক (Chief Accountant)
৪. সাধারণ শেয়ারহোল্ডার ও ভবিষ্যৎ বিনিয়োগকারী
৫. কোম্পানির অভ্যন্তরীণ নিরীক্ষক (Internal Auditor)
৬. কাঁচামাল সরবরাহকারী প্রতিষ্ঠান (পাওনাদার)

[করণীয়]:
ক) অভ্যন্তরীণ ব্যবহারকারী কারা তালিকাভুক্ত কর।
খ) বাহ্যিক ব্যবহারকারী কারা তালিকাভুক্ত কর।

[উত্তর]:
• **অভ্যন্তরীণ ব্যবহারকারী:**
  ১. ব্যবস্থাপনা পরিচালক
  ৩. প্রধান হিসাবরক্ষক
  ৫. অভ্যন্তরীণ নিরীক্ষক
• **বাহ্যিক ব্যবহারকারী:**
  ২. অগ্রণী ব্যাংক পিএলসি
  ৪. শেয়ারহোল্ডার ও ভবিষ্যৎ বিনিয়োগকারী
  ৬. কাঁচামাল সরবরাহকারী (পাওনাদার)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৪ (হিসাববিজ্ঞানের উৎপত্তি ও বিকাশ ধারা)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
হিসাববিজ্ঞানের ক্রমবিকাশকে কয়টি যুগে ভাগ করা হয় এবং লুকা প্যাসিওলির ভূমিকা কী?
[উত্তর]:
হিসাববিজ্ঞানের ক্রমবিকাশকে মূলত ৪টি যুগে ভাগ করা হয়:
১. উন্মেষ পর্ব (আদিম যুগ হতে ১৪৯৪ সাল পর্যন্ত)
২. প্রাক-বিশ্লেষণ পর্ব (১৪৯৪ হতে ১৭৯৫ সাল পর্যন্ত)
৩. বিশ্লেষণ পর্ব (১৮০০ হতে ১৯৫০ সাল পর্যন্ত)
৪. আধুনিক পর্ব (১৯৫০ সাল হতে বর্তমান সময়)
লুকা প্যাসিওলি ১৪৯৪ সালে দুতরফা দাখিলা পদ্ধতির দ্বৈত সত্তার নীতি সর্বপ্রথম ব্যাখ্যা করে হিসাববিজ্ঞানকে একটি বিজ্ঞানসম্মত শাস্ত্রের রূপ দেন।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৫ (মেয়ের আত্মমূল্যায়নের জন্য - Self Assessment)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
"হিসাববিজ্ঞান কেবল ব্যবসায়ের জন্যই নয়, ব্যক্তি ও পারিবারিক জীবনেও সমান উপযোগী"—উক্তিটি ব্যাখ্যা কর।
[সমাধান সংক্ষেপ]:
পরিবারে আয়ের একটি নির্দিষ্ট সীমা থাকে। যদি হিসাববিজ্ঞানের বাজেট ও ব্যয়ের হিসাব না রাখা হয়, তবে যেকোনো পরিবার দেনাগ্রস্ত হয়ে পড়তে পারে। পারিবারিক আয়-ব্যয়ের শৃঙ্খলা বজায় রেখে সঞ্চয় বাড়ানো এবং ভবিষ্যৎ সংকট মোকাবেলায় হিসাববিজ্ঞান সমানভাবে কাজ করে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ 📝 আপনার মেয়ের জন্য চূড়ান্ত ৫টি গোল্ডেন টিপস:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. **লুকা প্যাসিওলির তথ্য:** লুকা প্যাসিওলি ছিলেন ইতালির ধর্মযাজক ও গণিতবিদ; বইয়ের প্রকাশ সাল **১৪৯৪** (বোর্ড পরীক্ষার প্রিয় বহুনির্বাচনী প্রশ্ন)।
২. **ব্যবসায়ের ভাষা:** হিসাববিজ্ঞানকে "ব্যবসায়ের ভাষা" বলা হয় কারণ এটি আর্থিক খবরাখবর সবার নিকট বোধগম্য করে তুলে ধরে।
৩. **অভ্যন্তরীণ বনাম বাহ্যিক মনে রাখার ট্রিক:** যারা প্রতিদিন অফিস বা কারখানার ভেতরে বসে সিদ্ধান্ত নেন তারা "অভ্যন্তরীণ"; আর যারা প্রতিষ্ঠানের বাইরে থেকে সিদ্ধান্ত নেন (ব্যাংক, কর কর্মকর্তা, পাওনাদার) তারা "বাহ্যিক"।
৪. **হিসাববিজ্ঞানের প্রধান উদ্দেশ্য:** প্রথম উদ্দেশ্য হলো লেনদেন সুনির্দিষ্টভাবে লিপিবদ্ধ করা, আর চূড়ান্ত উদ্দেশ্য হলো আর্থিক ফলাফল ও আর্থিক অবস্থা নিরূপণ করা।
৫. **মূল্যবোধ ও সততা:** হিসাববিজ্ঞানের নিয়ম মেনে চললে সমাজে আর্থিক অপরাধ ও দুর্নীতি কমে আসে।$lesson$,
        6
    );

