-- ==================== seed_chapter_2_lendhen.sql ====================
-- ============================================================
-- Complete Educational Lessons & 30 Practice Questions
-- For Chapter 2: লেনদেন (Transaction)
-- Class 9 Bangladesh Curriculum - Accounting (হিসাববিজ্ঞান)
-- Includes:
-- 1. Concept of Transaction & 7 Essential Characteristics
-- 2. Events vs Transactions (All transactions are events, but not all events are transactions)
-- 3. Accounting Equation (A = L + E) & Tabular Analysis of Transactions
-- 4. Source Documents (Invoice/Challan, Cash Memo, Debit/Credit Voucher, Debit/Credit Note)
-- 5. Creative Questions 01 & 02 (Identification, Reasonings & Tabular Proof of A = L + E)
-- 6. Creative Questions 03, 04, 05 (Source Document Preparation & Final 5 Golden Tips)
-- 7. 30 Interactive Practice Questions (6 Checkpoint Rounds of 5 questions)
-- ============================================================

DO $$
DECLARE
    v_ch2_id UUID;
BEGIN
    -- 1. Find Chapter 2 ID strictly by order_index = 2
    SELECT id INTO v_ch2_id 
    FROM chapters 
    WHERE order_index = 2 
    LIMIT 1;

    IF v_ch2_id IS NULL THEN
        RAISE NOTICE 'Chapter 2 (লেনদেন) not found. Please run seed_accounting.sql first.';
        RETURN;
    END IF;

    -- Clean previous lessons and questions for Chapter 2
    DELETE FROM lessons WHERE chapter_id = v_ch2_id;
    DELETE FROM exam_questions WHERE chapter_id = v_ch2_id;

    -- ============================================================
    -- LESSON 1: লেনদেনের সহজ ধারণা ও আবশ্যকীয় ৭টি বৈশিষ্ট্য
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch2_id,
        $lesson$📌 পাঠ ১: লেনদেনের সহজ ধারণা ও আবশ্যকীয় ৭টি বৈশিষ্ট্য

হিসাববিজ্ঞানের প্রথম ও প্রধান ভিত্তি হলো **"লেনদেন (Transaction)"**। আভিধানিক অর্থে 'লেনদেন' শব্দের অর্থ হলো **"গ্রহণ ও দান"** (দেওয়া ও নেওয়া)। ইংরেজিতে একে বলা হয় **"Give and Take"**।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. লেনদেন কী?
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
অর্থের অঙ্কে পরিমাপযোগ্য এমন কোনো ঘটনা, যার মাধ্যমে কোনো ব্যক্তি বা প্রতিষ্ঠানের **আর্থিক অবস্থার পরিবর্তন** ঘটে, তাকে **লেনদেন (Transaction)** বলে।

• উদাহরণ:
  - ৫০,০০০ টাকার পণ্য নগদে ক্রয় করা হলো ➔ এটি লেনদেন (কারণ নগদ টাকা কমেছে এবং পণ্য সম্পদ/ব্যয় বেড়েছে)।
  - দোকান থেকে বাসায় যাওয়ার পথে মালিকের পকেটমার হলো ➔ এটি কারবারের লেনদেন নয় (ব্যক্তিগত ক্ষতি)।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. লেনদেনের আবশ্যকীয় ৭টি বৈশিষ্ট্য (Essential Characteristics):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
বোর্ড পরীক্ষায় যেকোনো ঘটনাকে লেনদেন হিসেবে প্রমাণ করতে নিচের ৭টি বৈশিষ্ট্য যাচাই করতে হয়:

১. **অর্থের অঙ্কে পরিমাপযোগ্যতা (Measurable in Money):** ঘটনাটি অবশ্যই নির্দিষ্ট অঙ্কের টাকায় পরিমাপযোগ্য হতে হবে (যেমন: ৫,০০০ টাকার মালামাল চুরি হলো—এটি লেনদেন; কিন্তু কর্মচারীর অসুস্থতা বা মৃত্যু লেনদেন নয়)।
২. **আর্থিক অবস্থার পরিবর্তন (Change in Financial Position):** ঘটনাটির ফলে প্রতিষ্ঠানের সম্পদ, দায় বা মালিকানাস্বত্বের যে কোনো একটির হ্রাস বা বৃদ্ধি ঘটতে হবে।
৩. **দ্বৈত সত্তা (Dual Aspect / Two Parties):** প্রতিটি লেনদেনে অবশ্যই দুটি স্বতন্ত্র পক্ষ থাকবে—একটি পক্ষ সুবিধা গ্রহণ করবে (ডেবিট) এবং অপর পক্ষ সুবিধা প্রদান করবে (ক্রেডিট)।
৪. **স্বয়ংসম্পূর্ণ ও স্বতন্ত্র (Independent & Complete):** প্রতিটি লেনদেন একটি অপরটি থেকে সম্পূর্ণ আলাদা। যেমন: ১৫ তারিখে ধারে পণ্য বিক্রয় একটি স্বতন্ত্র লেনদেন, আর ২৫ তারিখে সেই দেনাদারের নিকট থেকে টাকা আদায় অন্য একটি স্বতন্ত্র লেনদেন।
৫. **দৃশ্যমানতা (Visibility):** লেনদেন দৃশ্যমান হতে পারে (যেমন: নতুন আসবাবপত্র ক্রয়), আবার অদৃশ্যমানও হতে পারে (যেমন: আসবাবপত্রের ব্যবহারজনিত অবচয় বা ক্ষতি)।
৬. **ঐতিহাসিক ঘটনা (Historical Events):** অতীতে ঘটে যাওয়া কোনো আর্থিক ঘটনা লেনদেন (যেমন: গত মাসের বেতন প্রদান); আবার ভবিষ্যতে ঘটতে পারে এমন সম্ভাব্য ক্ষতিও লেনদেনের অন্তর্ভুক্ত হতে পারে (যেমন: অনাদায়ী পাওনা সঞ্চিতি)।
৭. **হিসাব সমীকরণে প্রভাব (Impact on Accounting Equation):** প্রতিটি লেনদেন অবশ্যই মৌলিক হিসাব সমীকরণ **A = L + E**-এর উপাদানসমূহে প্রভাব ফেলবে।$lesson$,
        1
    );

    -- ============================================================
    -- LESSON 2: ঘটনা বনাম লেনদেন (সকল লেনদেনই ঘটনা, কিন্তু...)
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch2_id,
        $lesson$📌 পাঠ ২: ঘটনা বনাম লেনদেন (সকল লেনদেনই ঘটনা, কিন্তু সকল ঘটনা লেনদেন নয়)

দৈনন্দিন জীবনে আমাদের চারপাশে হাজারো ঘটনা ঘটে। কিন্তু হিসাববিজ্ঞানের দৃষ্টিতে সব ঘটনাকে হিসাবের খাতায় লেখা হয় না।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সুবর্ণ নীতি:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
> **"সকল লেনদেনই ঘটনা, কিন্তু সকল ঘটনা লেনদেন নয়।"**
> (All transactions are events, but not all events are transactions.)

কোনো ঘটনা "লেনদেন" হতে হলে তাকে অবশ্যই প্রতিষ্ঠানের **আর্থিক অবস্থার বাস্তব পরিবর্তন** ঘটাতে হবে।

────────────────────────────
■ বোর্ড পরীক্ষার তুলনামূলক ছক (কোনটি লেনদেন এবং কোনটি নয়):
────────────────────────────
| ক্রঃ | সংঘটিত ঘটনা | লেনদেন কিনা? | কারণ ও যৌক্তিক ব্যাখ্যা |
| :---: | :--- | :---: | :--- |
| ১ | ৫০,০০০ টাকা দিয়ে ব্যবসায় শুরু করা হলো | **হ্যাঁ, লেনদেন** | কারবারে নগদ সম্পদ বৃদ্ধি (A+) ও মূলধন বৃদ্ধি (E+)। |
| ২ | মাসিক ১০,০০০ টাকা বেতনে ম্যানেজার নিয়োগ করা হলো | **না, লেনদেন নয়** | কেবল চুক্তি বা সিদ্ধান্ত হয়েছে; এখনও কোনো অর্থ আদান-প্রদান হয়নি। |
| ৩ | ১৫,০০০ টাকার পণ্য ক্রয়ের জন্য ফরমায়েশ (Order) দেওয়া হলো | **না, লেনদেন নয়** | এটি কেবল একটি প্রস্তাব বা অর্ডার; পণ্য পাওয়া যায়নি বা টাকাও দেওয়া হয়নি। |
| ৪ | ফরমায়েশকৃত ১৫,০০০ টাকার পণ্য নগদে গ্রহণ করা হলো | **হ্যাঁ, লেনদেন** | পণ্য প্রাপ্তির ফলে ব্যয় বৃদ্ধি এবং নগদ অর্থ চলে যাওয়ায় সম্পদ হ্রাস। |
| ৫ | ব্যক্তিগত তহবিল হতে ছেলের স্কুলের বেতন দেওয়া হলো ২,০০০ টাকা | **না, লেনদেন নয়** | এটি মালিকের ব্যক্তিগত খরচ, ব্যবসায়ের কোনো আর্থিক পরিবর্তন ঘটেনি। |
| ৬ | ব্যবসায়ের তহবিল হতে ছেলের স্কুলের বেতন দেওয়া হলো ২,০০০ টাকা | **হ্যাঁ, লেনদেন** | এটি কারবার থেকে মালিকের ব্যক্তিগত উত্তোলন (E-) এবং নগদ হ্রাস (A-)। |
| ৭ | কারবারের ক্যাশ বাক্স থেকে ৫,০০০ টাকা চুরি হলো | **হ্যাঁ, লেনদেন** | এটি একটি অপ্রত্যাশিত ক্ষতি/ব্যয় বৃদ্ধি এবং নগদ সম্পদ হ্রাস। |
| ৮ | মালিকের একটি মূল্যবান ব্যক্তিগত গাড়ি চুরি হলো | **না, লেনদেন নয়** | এটি মালিকের ব্যক্তিগত ক্ষতি, কারবারের আর্থিক অবস্থার ওপর কোনো প্রভাব নেই। |$lesson$,
        2
    );

    -- ============================================================
    -- LESSON 3: হিসাব সমীকরণ (A = L + E) ও লেনদেনের প্রভাব
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch2_id,
        $lesson$📌 পাঠ ৩: মৌলিক হিসাব সমীকরণ (A = L + E) ও লেনদেনের প্রভাব

হিসাববিজ্ঞানের সবচেয়ে গুরুত্বপূর্ণ গাণিতিক সমীকরণ হলো:
```
┌─────────────────────────────────────────────────────────────┐
│             A = L + E  (সম্পদ = দায় + মালিকানাস্বত্ব)       │
└─────────────────────────────────────────────────────────────┘
```

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সমীকরণের উপাদানসমূহের বিস্তারিত অর্থ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• **A (Assets - সম্পদ):** নগদ টাকা, ব্যাংক জমা, আসবাবপত্র, যন্ত্রপাতি, প্রাপ্য হিসাব (দেনাদার), সমাপনী মজুদ পণ্য।
• **L (Liabilities - দায়):** প্রদেয় হিসাব (পাওনাদার), ব্যাংক ঋণ, বকেয়া খরচ।
• **E (Equity - মালিকানাস্বত্ব):** ব্যবসায়ের মোট সম্পদে মালিকের দাবি।

────────────────────────────
■ মালিকানাস্বত্ব (E)-এর বর্ধিত রূপ:
────────────────────────────
`E = C + R - E - D`
• **C (Capital - মূলধন):** মালিকের প্রারম্ভিক বা অতিরিক্ত বিনিয়োগ (স্বত্ব বৃদ্ধি পায় +)
• **R (Revenues - রাজস্ব/আয়):** পণ্য বিক্রয় বা সেবা আয় (স্বত্ব বৃদ্ধি পায় +)
• **E (Expenses - ব্যয়/খরচ):** ক্রয়, বেতন, ভাড়া বা মনিহারি খরচ (স্বত্ব হ্রাস পায় -)
• **D (Drawings - উত্তোলন):** মালিকের ব্যক্তিগত প্রয়োজনে অর্থ বা পণ্য নেওয়া (স্বত্ব হ্রাস পায় -)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ লেনদেনের কারণে সমীকরণে ৫ ধরনের পরিবর্তন ঘটতে পারে:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. মোট সম্পদ বাড়লে মোট দায় অথবা মালিকানাস্বত্ব বাড়বে। (A+ হলে L+ অথবা E+)
   - যেমন: ধারে পণ্য ক্রয় ➔ মজুদ পণ্য (A+) ও পাওনাদার (L+)।
২. মোট সম্পদ কমলে মোট দায় অথবা মালিকানাস্বত্ব কমবে। (A- হলে L- অথবা E-)
   - যেমন: পাওনাদারকে পরিশোধ ➔ নগদ (A-) ও পাওনাদার (L-)।
৩. একটি সম্পদ বাড়লে অপর একটি সম্পদ কমবে। (A+ এবং A-)
   - যেমন: নগদে আসবাবপত্র ক্রয় ➔ আসবাবপত্র (A+) ও নগদ টাকা (A-)।
৪. একটি দায় বাড়লে অপর একটি দায় কমবে। (L+ এবং L-)
   - যেমন: পাওনাদারকে পরিশোধের জন্য ব্যাংক ঋণ গ্রহণ ➔ ঋণ (L+) ও পাওনাদার (L-)।
৫. মালিকানাস্বত্ব বাড়লে দায় কমবে বা বিপরীত হবে। (E+ এবং L-)$lesson$,
        3
    );

    -- ============================================================
    -- LESSON 4: লেনদেনের উৎস দলিল ও প্রমাণপত্র (চালান, ভাউচার ও মেমো)
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch2_id,
        $lesson$📌 পাঠ ৪: লেনদেনের উৎস দলিল ও প্রমাণপত্র (চালান, ভাউচার, ক্যাশমেমো)

কোনো লেনদেন হিসাবের বইয়ে লেখার আগে তার সমর্থনে নির্ভরযোগ্য লিখিত প্রমাণপত্র বা দলিল থাকতে হয়।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ প্রধান প্রধান উৎস দলিলসমূহ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━

### ১. চালান (Invoice / Challan):
• **প্রকৃতি:** পণ্য **ধারে ক্রয়-বিক্রয়ের** প্রধান প্রামাণ্য দলিল।
• **প্রস্তুতকারী:** বিক্রেতা তৈরি করেন এবং ক্রেতাকে পণ্যের বিবরণী ও মোট মূল্যের একটি কপি পাঠান।
• চালানের ওপর ভিত্তি করে ক্রেতা লেখেন **"ক্রয় জাবেদা"** এবং বিক্রেতা লেখেন **"বিক্রয় জাবেদা"**।
• চালানে কারবারি বাট্টা (Trade Discount), প্যাকিং খরচ ও পরিবহনের বিস্তারিত উল্লেখ থাকে।

### ২. ক্যাশমেমো (Cash Memo):
• **প্রকৃতি:** পণ্য **নগদে ক্রয়-বিক্রয়ের** লিখিত প্রমাণপত্র।
• **প্রস্তুতকারী:** বিক্রেতা নগদে পণ্য বিক্রয়ের সময় ৩ প্রস্থে ক্যাশমেমো তৈরি করেন (মূল কপি ক্রেতাকে দেন এবং কার্বন কপি নিজের কাছে রাখেন)।

### ৩. ডেবিট ভাউচার (Debit Voucher):
• **প্রকৃতি:** কারবারের **যাবতীয় খরচের বা নগদ ক্রয়ের** স্বপক্ষে ব্যবহৃত দলিল।
• যেমন: পণ্য ক্রয়, কর্মচারীর বেতন প্রদান, দোকান ভাড়া, মনিহারি ইত্যাদির সাথে রসিদ সংযুক্ত করে ডেবিট ভাউচার করা হয়।

### ৪. ক্রেডিট ভাউচার (Credit Voucher):
• **প্রকৃতি:** কারবারের **যাবতীয় আয় বা নগদ বিক্রয়ের** স্বপক্ষে ব্যবহৃত দলিল।
• যেমন: পণ্য বিক্রয়, উপভাড়া প্রাপ্তি, কমিশন প্রাপ্তির হিসাব ক্রেডিট ভাউচারে থাকে।

### ৫. ডেবিট নোট (Debit Note):
• **প্রকৃতি:** ক্রেতা যখন ধারে ক্রয়কৃত ত্রুটিপূর্ণ পণ্য বিক্রেতার নিকট **ফেরত পাঠান**, তখন বিক্রেতার হিসাবকে ডেবিট করা হয়েছে জানিয়ে যে চিঠি পাঠান, তাকে **ডেবিট নোট** বলে। (ক্রয় ফেরতের প্রমাণ)।

### ৬. ক্রেডিট নোট (Credit Note):
• **প্রকৃতি:** বিক্রিত পণ্য ক্রেতার নিকট থেকে ফেরত আসলে বিক্রেতা ক্রেতার হিসাবকে ক্রেডিট করেছেন মর্মে যে চিঠি পাঠান, তাকে **ক্রেডিট নোট** বলে। (বিক্রয় ফেরতের প্রমাণ)।$lesson$,
        4
    );

