    VALUES (
        v_ch2_id,
        $lesson$📌 পাঠ ৫: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২ (পূর্ণাঙ্গ সমাধান)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০১ (ঘটনা বনাম লেনদেন ও কারণ ব্যাখ্যা)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব রাফসান ২০২৩ সালের মার্চ মাসে নিচের ব্যবসায়িক কার্যক্রম সম্পন্ন করেন:
• মার্চ ১: নগদ ৮০,০০০ টাকা ও ২০,০০০ টাকার পণ্য নিয়ে ব্যবসা শুরু করলেন।
• মার্চ ৫: সোনালী ব্যাংকে কারবারের নামে একটি চলতি হিসাব খোলা হলো ১৫,০০০ টাকা দিয়ে।
• মার্চ ১০: মাসিক ৮,০০০ টাকা বেতনে একজন বিক্রয়কর্মী নিয়োগের সিদ্ধান্ত গৃহীত হলো।
• মার্চ ১৫: জনাব কবিরের নিকট হতে ২৫,০০০ টাকার পণ্য ক্রয়ের ফরমায়েশ পাওয়া গেল।
• মার্চ ২০: ব্যক্তিগত তহবিল হতে ব্যবসায়ের বিদ্যুৎ বিল পরিশোধ করলেন ৩,০০০ টাকা।
• মার্চ ২৮: দোকান হতে নগদ ২,০০০ টাকা হারিয়ে গেল।

[করণীয় প্রশ্ন]:
ক) যে সকল ঘটনা লেনদেন নয়, তার মোট পরিমাণ নির্ণয় কর।
খ) মার্চ ১, ৫ ও ২০ তারিখের লেনদেনগুলোর সমীকরণ উপাদান (A, L, E) কারণসহ ব্যাখ্যা কর।
গ) মার্চ ২৮ তারিখের ঘটনাটি লেনদেন কিনা যুক্তিসহ প্রতিপন্ন কর।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) যে সকল ঘটনা লেনদেন নয় তার তালিকা ও পরিমাণ:**
| তারিখ | বিবরণ | টাকা |
| :---: | :--- | :---: |
| মার্চ ১০ | বিক্রয়কর্মী নিয়োগের সিদ্ধান্ত গ্রহণ (কোনো আর্থিক পরিবর্তন হয়নি) | ৮,০০০ |
| মার্চ ১৫ | পণ্য ক্রয়ের ফরমায়েশ প্রাপ্তি (কেবল চুক্তি, পণ্য বা টাকা দেওয়া হয়নি) | ২৫,০০০ |
| **মোট** | **যে ঘটনাগুলো লেনদেন নয়** | **৩৩,০০০** |

**খ) লেনদেনসমূহের সমীকরণ উপাদান বিশ্লেষণ:**
| তারিখ | সংশ্লিষ্ট হিসাব | সমীকরণ পরিবর্তন | কারণ ব্যাখ্যা |
| :---: | :--- | :---: | :--- |
| মার্চ ১ | নগদান হিসাব (Dr.)<br>মজুদ পণ্য (Dr.)<br>মূলধন হিসাব (Cr.) | A বৃদ্ধি (+)<br>A বৃদ্ধি (+)<br>E বৃদ্ধি (+) | নগদ সম্পদ ও পণ্য সম্পদ কারবারে বেড়েছে এবং মালিকের প্রারম্ভিক মূলধন/স্বত্ব বেড়েছে। |
| মার্চ ৫ | ব্যাংক হিসাব (Dr.)<br>নগদান হিসাব (Cr.) | A বৃদ্ধি (+)<br>A হ্রাস (-) | ব্যাংকে জমা বেড়ে এক সম্পদ বেড়েছে (A+) এবং হাত থেকে নগদ টাকা কমে অপর সম্পদ হ্রাস পেয়েছে (A-)। |
| মার্চ ২০ | বিদ্যুৎ খরচ হিসাব (Dr.)<br>মূলধন হিসাব (Cr.) | E হ্রাস (-)<br>E বৃদ্ধি (+) | বিদ্যুৎ ব্যয়ের কারণে খরচ বেড়েছে এবং মালিকের ব্যক্তিগত তহবিল দেওয়ায় অতিরিক্ত মূলধন বৃদ্ধি পেয়েছে। |

**গ) মার্চ ২৮ তারিখের ঘটনাটি লেনদেন কিনা মূল্যায়ন:**
মার্চ ২৮ তারিখে দোকান হতে নগদ ২,০০০ টাকা হারিয়ে যাওয়া **একটি নিশ্চিত লেনদেন**।
• **যুক্তি:**
  ১. এটি ২,০০০ টাকার অঙ্কে সুনির্দিষ্টভাবে পরিমাপযোগ্য।
  ২. কারবারের নগদ তহবিল থেকে ২,০০০ টাকা হ্রাস পেয়ে সম্পদ হ্রাস (A-) ঘটেছে।
  ৩. এটি 'বিবিধ ক্ষতি' নামের একটি অনাকাঙ্ক্ষিত লোকসান যা মালিকানাস্বত্বকে (E-) সরাসরি কমিয়ে দেয়।
অতএব, এটি হিসাববিজ্ঞানের নিয়মানুযায়ী একটি স্বীকৃত লেনদেন।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০২ (হিসাব সমীকরণ বিবরণী ছকে প্রভাব A = L + E)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
মিসেস নুসরাতের ব্যবসায়ের এপ্রিল ২০২৩-এর লেনদেনসমূহ:
১. এপ্রিল ১: নগদ ৫০,০০০ টাকা নিয়ে ব্যবসা আরম্ভ।
২. এপ্রিল ৭: ধারে আসবাবপত্র ক্রয় ২০,০০০ টাকা।
৩. এপ্রিল ১২: ধারে পণ্য বিক্রয় ৩০,০০০ টাকা।
৪. এপ্রিল ২০: আসবাবপত্রের পাওনাদারকে পরিশোধ ১০,০০০ টাকা।

[করণীয় প্রশ্ন]:
বিবরণী ছকে হিসাব সমীকরণের ওপর (A = L + E) লেনদেনগুলোর প্রভাব দেখাও।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**বিবরণী ছকে হিসাব সমীকরণের প্রমাণ (A = L + E):**
| তারিখ | সম্পদ = নগদ + আসবাবপত্র + দেনাদার | = | দায় (পাওনাদার) | + | মালিকানাস্বত্ব (মূলধন) | মন্তব্য |
| :---: | :---: | :---: | :---: | :---: | :---: | :--- |
| এপ্রিল ১ | +৫০,০০০ | = | — | + | +৫০,০০০ | মূলধন বিনিয়োগ |
| এপ্রিল ৭ | +২০,০০০ (আসবাবপত্র) | = | +২০,০০০ | + | — | ধারে আসবাবপত্র ক্রয় |
| এপ্রিল ১২ | +৩০,০০০ (দেনাদার) | = | — | + | +৩০,০০০ | ধারে বিক্রয় (আয়) |
| এপ্রিল ২০ | -১০,০০০ (নগদ) | = | -১০,০০০ | + | — | পাওনাদারকে পরিশোধ |
| **জের** | **৪০,০০০ + ২০,০০০ + ৩০,০০০ = ৯০,০০০** | = | **১০,০০০** | + | **৮০,০০০ = ৯০,০০০** | **প্রমাণিত: A = L + E** |$lesson$,
        5
    );

