        $lesson$📌 পাঠ ৬: সৃজনশীল প্রশ্ন ০৩, ০৪, ০৫ ও ফাইনাল ৫টি গোল্ডেন টিপস

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৩ (চালান ও ডেবিট নোটের কাঠামো)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
২০২৩ সালের মে ৫ তারিখে 'মেসার্স সীমান্ত ট্রেডার্স', 'মেঘনা ব্রাদার্স'-এর নিকট হতে প্রতি কেজি ১০০ টাকা দরে ২০০ কেজি চাল ধারে ক্রয় করেন। কারবারি বাট্টা ১০%, চালান নং-১০১ এবং শর্ত ২/১০, নিট ৩০। মে ১০ তারিখে নষ্ট থাকায় ২০ কেজি চাল ফেরত পাঠানো হলো (ডেবিট নোট নং-১৫)।

[করণীয় ও সমাধান]:
**ক) চালানের মোট নিট মূল্যের পরিমাণ:**
• মোট ক্রয় মূল্য = ২০০ কেজি × ১০০ টাকা = ২০,০০০ টাকা।
• বাদ: কারবারি বাট্টা (১০%) = ২,০০০ টাকা।
➔ **চালানের নিট মূল্য = ১৮,০০০ টাকা**।

**খ) ডেবিট নোটের ফেরত পণ্যের মূল্য:**
• ফেরত পণ্যের মূল্য = ২০ কেজি × ১০০ টাকা = ২,০০০ টাকা।
• বাদ: কারবারি বাট্টা (১০%) = ২০০ টাকা।
➔ **ডেবিট নোটে ফেরত মূল্য = ১,৮০০ টাকা**।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৪ (লেনদেনের দৃশ্যমানতা ও অদৃশ্যমানতা)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
"লেনদেন কেবল দৃশ্যমানই নয়, অদৃশ্যমানও হতে পারে"—উদাহরণসহ বুঝিয়ে দাও।
[উত্তর]:
আমরা সচরাচর নগদ বা চেকের মাধ্যমে পণ্য বা আসবাবপত্র ক্রয়-বিক্রয় দেখতে পাই, যা দৃশ্যমান লেনদেন। কিন্তু স্থায়ী সম্পদ ব্যবহারের ফলে যে মূল্যহ্রাস ঘটে (অবচয়), কিংবা দেনাদারের কাছ থেকে অর্থ আদায়ের অনিশ্চয়তা (অনাদায়ী পাওনা)—তা চোখে দেখা যায় না কিন্তু ব্যবসায়ের সম্পদ ও আর্থিক অবস্থা বাস্তবিকভাবে কমিয়ে দেয়। তাই অবচয় বা অনাদায়ী পাওনা হলো অদৃশ্যমান লেনদেনের উৎকৃষ্ট উদাহরণ।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৫ (মেয়ের আত্মমূল্যায়নের জন্য - Self Assessment)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
মালিকের বাড়ি ভাড়ার টাকা কি কারবারের হিসাব সমীকরণে আসবে? কেন?
[সমাধান সংক্ষেপ]:
যদি মালিক নিজের পকেটের টাকা দিয়ে নিজের বাড়ি ভাড়া দেন, তবে তা কারবারের সমীকরণে আসবে না (ব্যক্তিগত লেনদেন)। কিন্তু যদি কারবারের ক্যাশ বাক্স থেকে সেই বাড়ি ভাড়া দেওয়া হয়, তবে তা 'উত্তোলন' হিসেবে সমীকরণে নগদ সম্পদ (A-) এবং মালিকানাস্বত্ব (E-) উভয়ই কমিয়ে দেবে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ 📝 আপনার মেয়ের জন্য চূড়ান্ত ৫টি গোল্ডেন টিপস:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. **নিয়োগ বা ফরমায়েশ কখনো লেনদেন নয়:** প্রশ্নপত্রে যদি 'নিয়োগ দেওয়া হলো', 'চুক্তি করা হলো' বা 'অর্ডার দেওয়া হলো' থাকে—চোখ বন্ধ করে মনে রাখবে এগুলো লেনদেন নয়!
২. **ব্যক্তিগত বনাম কারবারি খরচ:** ব্যক্তিগত পকেট থেকে ব্যক্তিগত খরচ লেনদেন নয়; কিন্তু কারবারের তহবিল ছুঁলেই তা লেনদেন হয়ে যায়।
৩. **A = L + E সমতার ম্যাজিক:** প্রতিটি বিবরণী অংকে বাম পাশের সম্পদের মোট যোগফল সবসময় ডান পাশের (দায় + মূলধনের) যোগফলের হুবহু সমান হবে।
৪. **চালান ধারে বিক্রয়ে, ক্যাশমেমো নগদে:** এটি বোর্ড পরীক্ষার বহুনির্বাচনীর জন্য সবচেয়ে কমন ট্রিক।
৫. **ডেবিট নোট ক্রেতা তৈরি করেন, ক্রেডিট নোট বিক্রেতা:** ডেবিট নোটে থাকে ক্রয় ফেরত, ক্রেডিট নোটে থাকে বিক্রয় ফেরত।$lesson$,
        6
    );

