-- ==================== seed_chapter_3_double_entry.sql ====================
-- ============================================================
-- Complete Educational Lessons & 30 Practice Questions
-- For Chapter 3: দুতরফা দাখিলা পদ্ধতি (Double Entry System)
-- Class 9 Bangladesh Curriculum - Accounting (হিসাববিজ্ঞান)
-- Includes:
-- 1. Double Entry Principles & 5 Core Characteristics
-- 2. Modern vs Traditional Debit & Credit Rules with Magic Table
-- 3. The 10 Steps of the Accounting Cycle (Flowchart & Explanations)
-- 4. Single Entry System (Formulas for Opening/Closing Capital & Profit/Loss)
-- 5. Creative Questions 01 & 02 (Debit-Credit Reasoning & Single Entry Math)
-- 6. Creative Questions 03, 04, 05 (Cycle Analysis, Self-Assessment & 5 Golden Tips)
-- 7. 30 Interactive Practice Questions (6 Checkpoint Rounds of 5 questions)
-- ============================================================

DO $$
DECLARE
    v_ch3_id UUID;
BEGIN
    -- 1. Find Chapter 3 ID strictly by order_index = 3
    SELECT id INTO v_ch3_id 
    FROM chapters 
    WHERE order_index = 3 
    LIMIT 1;

    IF v_ch3_id IS NULL THEN
        RAISE NOTICE 'Chapter 3 (দুতরফা দাখিলা পদ্ধতি) not found. Please run seed_accounting.sql first.';
        RETURN;
    END IF;

    -- Clean previous lessons and questions for Chapter 3
    DELETE FROM lessons WHERE chapter_id = v_ch3_id;
    DELETE FROM exam_questions WHERE chapter_id = v_ch3_id;

    -- ============================================================
    -- LESSON 1: দুতরফা দাখিলা পদ্ধতির মূল ধারণা ও ৫টি বৈশিষ্ট্য
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch3_id,
        $lesson$📌 পাঠ ১: দুতরফা দাখিলা পদ্ধতির মূল ধারণা ও ৫টি আবশ্যকীয় বৈশিষ্ট্য

হিসাববিজ্ঞানের ইতিহাসে সবচেয়ে বৈজ্ঞানিক ও নির্ভুল হিসাবরক্ষণ ব্যবস্থার নাম হলো **"দুতরফা দাখিলা পদ্ধতি (Double Entry System)"**। ১৪৯৪ সালে ইতালির গণিতবিদ **লুকা প্যাসিওলি** এই পদ্ধতির মূলনীতি প্রথম প্রকাশ করেন।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. দুতরফা দাখিলা পদ্ধতি কী?
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
যে হিসাবরক্ষণ পদ্ধতিতে প্রতিটি আর্থিক লেনদেনের **দ্বৈত সত্তা** বিচার করে একটি পক্ষকে সুবিধা গ্রহণকারী হিসেবে সমপরিমাণ অর্থে **ডেবিট (Debit)** এবং অপর পক্ষকে সুবিধা প্রদানকারী হিসেবে সমপরিমাণ অর্থে **ক্রেডিট (Credit)** করা হয়, তাকে **দুতরফা দাখিলা পদ্ধতি** বলে।

• মূলনীতি: **মোট ডেবিট টাকা = মোট ক্রেডিট টাকা** (Total Debit = Total Credit)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. দুতরফা দাখিলা পদ্ধতির ৫টি প্রধান বৈশিষ্ট্য:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. **দ্বৈত সত্তা (Dual Aspect):** প্রতিটি লেনদেনে অবশ্যই দুটি ভিন্ন পক্ষ বা হিসাব জড়িত থাকবে। একটি পক্ষ সুবিধা গ্রহণ করবে এবং অপর পক্ষ সুবিধা প্রদান করবে।
২. **দাতা ও গ্রহীতা (Giver & Receiver):** প্রতিটি লেনদেনে সুবিধা গ্রহণকারী পক্ষ হবে 'গ্রহীতা' (Debtor/Debit) এবং সুবিধা প্রদানকারী পক্ষ হবে 'দাতা' (Creditor/Credit)।
৩. **সমান অংকের আদান-প্রদান (Equal Amount):** ডেবিট পাশে যে পরিমাণ টাকা লেখা হবে, ঠিক সমপরিমাণ টাকা ক্রেডিট পাশেও বসবে।
৪. **সামগ্রিক ফলাফল নির্ণয় (Ascertaining Overall Result):** আয়-ব্যয় এবং সম্পদ-দায়ের পূর্ণাঙ্গ হিসাব থাকায় নির্দিষ্ট সময় শেষে কারবারের সঠিক নিট লাভ বা ক্ষতি এবং আর্থিক অবস্থা নির্ভুলভাবে নির্ণয় করা যায়।
৫. **গাণিতিক শুদ্ধতা যাচাই (Mathematical Accuracy):** উভয় পাশের টাকা সমান হওয়ার কারণে বছর শেষে 'রেওয়ামিল (Trial Balance)' তৈরির মাধ্যমে হিসাবের গাণিতিক নির্ভুলতা তাৎক্ষণিকভাবে পরীক্ষা করা যায়।$lesson$,
        1
    );

    -- ============================================================
    -- LESSON 2: ডেবিট ও ক্রেডিট নির্ণয়ের আধুনিক সুবর্ণ সূত্র
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch3_id,
        $lesson$📌 পাঠ ২: ডেবিট ও ক্রেডিট নির্ণয়ের আধুনিক সুবর্ণ সূত্রাবলী

দুতরফা দাখিলা পদ্ধতিতে হিসাব সমীকরণের (A = L + E) ভিত্তিতে ডেবিট-ক্রেডিট নির্ণয় করা হয়।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ আধুনিক ম্যাজিক চার্ট (Modern Golden Rules):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
হিসাবের ৫টি মূল উপাদানের ক্ষেত্রে ডেবিট-ক্রেডিট নিয়মটি নিচে সাজিয়ে দেওয়া হলো:

| হিসাবের শ্রেণি | বৃদ্ধি পেলে (+) | হ্রাস পেলে (-) | মনে রাখার সহজ কৌশল |
| :--- | :---: | :---: | :--- |
| **১. সম্পদ (Assets - A)** | **ডেবিট (Dr.)** | **ক্রেডিট (Cr.)** | সম্পদ ও ব্যয় এক দলের (বাড়লে ডেবিট) |
| **২. ব্যয় (Expenses - E)** | **ডেবিট (Dr.)** | **ক্রেডিট (Cr.)** | ব্যয় সবসময় ডেবিট উদ্বৃত্ত প্রকাশ করে |
| **৩. দায় (Liabilities - L)** | **ক্রেডিট (Cr.)** | **ডেবিট (Dr.)** | দায়, মূলধন ও আয় বিপরীত দলের (বাড়লে ক্রেডিট) |
| **৪. মালিকানাস্বত্ব (Equity - E)**| **ক্রেডিট (Cr.)** | **ডেবিট (Dr.)** | মালিকের মূলধন কারবারের দায় বাড়ায় |
| **৫. আয় বা রাজস্ব (Revenues - R)**| **ক্রেডিট (Cr.)** | **ডেবিট (Dr.)** | আয় হলে মালিকের স্বত্ব বাড়ে |

────────────────────────────
■ বাস্তব লেনদেনে প্রয়োগ ও কারণ ব্যাখ্যা:
────────────────────────────
১. **নগদে পণ্য বিক্রয় ৫০,০০০ টাকা:**
   • নগদান হিসাব ডেবিট (৫০,০০০ টাকা) ➔ সম্পদ বৃদ্ধি (A+)
   • বিক্রয় হিসাব ক্রেডিট (৫০,০০০ টাকা) ➔ আয় বৃদ্ধি (R+)
২. **কর্মচারীকে বেতন প্রদান ১০,০০০ টাকা:**
   • বেতন হিসাব ডেবিট (১০,০০০ টাকা) ➔ ব্যয় বৃদ্ধি (E+)
   • নগদান হিসাব ক্রেডিট (১০,০০০ টাকা) ➔ সম্পদ হ্রাস (A-)
৩. **ধারে যন্ত্রপাতি ক্রয় ৪০,০০০ টাকা:**
   • যন্ত্রপাতি হিসাব ডেবিট (৪০,০০০ টাকা) ➔ সম্পদ বৃদ্ধি (A+)
   • প্রদেয় হিসাব ক্রেডিট (৪০,০০০ টাকা) ➔ দায় বৃদ্ধি (L+)$lesson$,
        2
    );

    -- ============================================================
    -- LESSON 3: হিসাবচক্রের ১০টি পর্যায়বৃত্ত ধাপ (Accounting Cycle)
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch3_id,
        $lesson$📌 পাঠ ৩: হিসাবচক্রের ১০টি পর্যায়বৃত্ত ধাপ (Accounting Cycle)

হিসাববিজ্ঞান একটি অবিরাম ও ধারাবাহিক প্রক্রিয়া। একটি নির্দিষ্ট হিসাবকালে হিসাবের কার্যাবলি চক্রাকারে আবর্তিত হয়, যাকে **হিসাবচক্র (Accounting Cycle)** বলে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ হিসাবচক্রের ধারাবাহিক ১০টি ধাপ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
```
১. লেনদেন শনাক্তকরণ ➔ ২. লেনদেন বিশ্লেষণ ➔ ৩. জাবেদাভুক্তকরণ ➔ ৪. খতিয়ানে স্থানান্তর ➔ 
৫. রেওয়ামিল প্রস্তুত ➔ ৬. সমন্বয় দাখিলা ➔ ৭. কার্যপত্র (ঐচ্ছিক) ➔ ৮. আর্থিক বিবরণী ➔ 
৯. সমাপনী দাখিলা ➔ ১০. সমাপনী-উত্তর রেওয়ামিল (হিসাব পরবর্তী)
```

────────────────────────────
■ ধাপসমূহের সারসংক্ষেপ:
────────────────────────────
১. **লেনদেন শনাক্তকরণ (Identifying):** ঘটনাগুলোর মধ্য থেকে কোনটি লেনদেন তা প্রমাণপত্র দেখে চিহ্নিত করা।
২. **লেনদেন বিশ্লেষণ (Analyzing):** লেনদেনের দুটি পক্ষ (ডেবিট ও ক্রেডিট) বের করা।
৩. **জাবেদাভুক্তকরণ (Journalizing):** হিসাবের প্রাথমিক বইয়ে তারিখ অনুযায়ী ডেবিট-ক্রেডিট ও ব্যাখ্যাসহ লেখা।
৪. **খতিয়ানে স্থানান্তর (Posting to Ledger):** জাবেদা থেকে লেনদেনগুলোকে পৃথক শিরোনামে পাকা বইয়ে পোস্টিং করা।
৫. **রেওয়ামিল প্রস্তুত (Trial Balance):** খতিয়ানের ডেবিট ও ক্রেডিট জের নিয়ে গাণিতিক নির্ভুলতা যাচাই করা।
৬. **সমন্বয় দাখিলা (Adjusting Entries):** বকেয়া খরচ, অগ্রিম আয়, অবচয় ইত্যাদিকে চলতি বছরের হিসাবে সমন্বিত করা।
৭. **কার্যপত্র প্রস্তুত (Worksheet):** আর্থিক বিবরণী সহজে প্রস্তুত করার জন্য ১০ বা ১২ কলামের একটি খসড়া বিবরণী (এটি ঐচ্ছিক ধাপ)।
৮. **আর্থিক বিবরণী (Financial Statements):** লাভ-ক্ষতি ও আর্থিক অবস্থা নির্ণয়ের চূড়ান্ত বিবরণী তৈরি।
৯. **সমাপনী দাখিলা (Closing Entries):** চলতি বছরের মুনাফাজাতীয় আয় ও ব্যয় হিসাবগুলোকে বন্ধ করে দেওয়া।
১০. **হিসাব পরবর্তী রেওয়ামিল (Post-Closing Trial Balance):** আগামী বছরের জন্য শুধুমাত্র সম্পদ ও দায় নিয়ে নতুন রেওয়ামিল তৈরি।$lesson$,
        3
    );

    -- ============================================================
    -- LESSON 4: একতরফা দাখিলা পদ্ধতি ও লাভ-ক্ষতি নির্ণয়
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch3_id,
        $lesson$📌 পাঠ ৪: একতরফা দাখিলা পদ্ধতি ও লাভ-ক্ষতি নির্ণয়ের সূত্র

ছোট ছোট মুদি দোকান বা ব্যক্তি যারা দুতরফা দাখিলার মতো কঠোর বিজ্ঞানসম্মত নিয়ম মেনে চলেন না, তারা **একতরফা দাখিলা পদ্ধতি (Single Entry System)** অনুসরণ করেন।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ একতরফা দাখিলা পদ্ধতির প্রকৃতি:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• এটি কোনো বিজ্ঞানসম্মত পদ্ধতি নয়; এটি একটি অসম্পূর্ণ ও বিভ্রান্তিকর পদ্ধতি।
• এতে কোনো কোনো লেনদেনের উভয় পক্ষ লেখা হয় (নগদ লেনদেন), কোনোটির এক পক্ষ লেখা হয় (ধারে কেনাবেচা), আবার কোনোটির কোনো পক্ষই লেখা হয় না (অবচয়)।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ একতরফা পদ্ধতিতে লাভ-ক্ষতি নির্ণয়ের ৩টি সুবর্ণ সূত্র:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━

### ১. প্রারম্ভিক মূলধন নির্ণয় (০১.০১ তারিখে):
`প্রারম্ভিক মূলধন = প্রারম্ভিক মোট সম্পদ - প্রারম্ভিক মোট দায়`

### ২. সমাপনী মূলধন নির্ণয় (৩১.১২ তারিখে):
`সমাপনী মূলধন = সমাপনী মোট সম্পদ - সমাপনী মোট দায়`

### ৩. লাভ বা ক্ষতি নির্ণয়ের চূড়ান্ত সূত্র:
```
লাভ বা ক্ষতি = (সমাপনী মূলধন + উত্তোলন) - (প্রারম্ভিক মূলধন + অতিরিক্ত মূলধন)
```
• ফলাফল ধনাত্মক (+) আসলে = **নিট লাভ**।
• ফলাফল ঋণাত্মক (-) আসলে = **নিট ক্ষতি**।$lesson$,
        4
    );

    -- ============================================================
    -- LESSON 5: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch3_id,
        $lesson$📌 পাঠ ৫: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২ (পূর্ণাঙ্গ সমাধান)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০১ (ডেবিট ও ক্রেডিট নির্ণয় এবং কারণ ব্যাখ্যা)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব তাহসিনের ২০২৩ সালের মে মাসের কয়েকটি লেনদেন নিচে দেওয়া হলো:
• মে ১: নগদ ৫০,০০০ টাকা এবং ৩০,০০০ টাকার ব্যাংক জমা নিয়ে ব্যবসা শুরু করলেন।
• মে ৮: ধারে পণ্য ক্রয় ২৫,০০০ টাকা।
• মে ১৫: বাকিতে পণ্য বিক্রয় ৪০,০০০ টাকা।
• মে ২০: আসবাবপত্রের ওপর অবচয় ধার্য করা হলো ২,০০০ টাকা।
• মে ২৫: ব্যাংক হতে ঋণ গ্রহণ ৩০,০০০ টাকা।

[করণীয় প্রশ্ন]:
ক) জনাব তাহসিনের প্রারম্ভিক মূলধনের পরিমাণ কত?
খ) মে ৮, ১৫ ও ২০ তারিখের লেনদেনের ডেবিট ও ক্রেডিট পক্ষ কারণসহ নির্ণয় কর।
গ) মে ২৫ তারিখের লেনদেনটি হিসাব সমীকরণে কী পরিবর্তন আনে তা ব্যাখ্যা কর।

────────────────────────────
[উত্তর ও সমাধান]:

**ক) জনাব তাহসিনের প্রারম্ভিক মূলধন:**
• প্রারম্ভিক নগদ = ৫০,০০০ টাকা
• প্রারম্ভিক ব্যাংক জমা = ৩০,০০০ টাকা
➔ **মোট প্রারম্ভিক মূলধন = ৮০,০০০ টাকা**।

**খ) কারণসহ ডেবিট ও ক্রেডিট নির্ণয় ছক:**
| তারিখ | সংশ্লিষ্ট হিসাবসমূহ | ডেবিট / ক্রেডিট | টাকা | কারণ ব্যাখ্যা (সমীকরণ প্রভাব) |
| :---: | :--- | :---: | :---: | :--- |
| মে ৮ | ক্রয় হিসাব<br>প্রদেয় হিসাব | ডেবিট<br>ক্রেডিট | ২৫,০০০<br>২৫,০০০ | পণ্য ক্রয়ের ফলে ব্যয় বৃদ্ধি (E+)<br>ধারে ক্রয়ের ফলে পাওনাদার দায় বৃদ্ধি (L+) |
| মে ১৫ | প্রাপ্য হিসাব<br>বিক্রয় হিসাব | ডেবিট<br>ক্রেডিট | ৪০,০০০<br>৪০,০০০ | দেনাদারের নিকট দাবি/সম্পদ বৃদ্ধি (A+)<br>পণ্য বিক্রয়ের ফলে আয় বৃদ্ধি (R+) |
| মে ২০ | অবচয় হিসাব<br>পুঞ্জীভূত অবচয় হিসাব | ডেবিট<br>ক্রেডিট | ২,০০০<br>২,০০০ | ব্যবহারজনিত ক্ষতি বা ব্যয় বৃদ্ধি (E+)<br>বিপরীত সম্পদ দ্বারা সম্পদ হ্রাস (A-) |

**গ) মে ২৫ তারিখের সমীকরণ বিশ্লেষণ:**
ব্যাংক থেকে ঋণ গ্রহণ ৩০,০০০ টাকা:
• কারবারের ব্যাংক হিসাবে নগদ টাকা জমা বৃদ্ধি পাওয়ায় **সম্পদ বৃদ্ধি (A+)** পেয়েছে ৩০,০০০ টাকা।
• ব্যাংকের নিকট দেনা সৃষ্টি হওয়ায় প্রতিষ্ঠানের **দায় বৃদ্ধি (L+)** পেয়েছে ৩০,০০০ টাকা।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০২ (একতরফা দাখিলা পদ্ধতিতে লাভ-ক্ষতি নির্ণয়)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব সোলায়মান দুতরফা দাখিলা অনুযায়ী হিসাব রাখেন না। ১ জানুয়ারি ২০২৩ তারিখে তাঁর মোট সম্পদ ছিল ২,৫০,০০০ টাকা এবং মোট দায় ছিল ৭০,০০০ টাকা। ৩১ ডিসেম্বর ২০২৩ তারিখে তাঁর মোট সম্পদ দাঁড়ায় ৩,২০,০০০ টাকা এবং মোট দায় ৬০,০০০ টাকা। উক্ত বছরে তিনি ব্যবসায়ে নতুন করে ২০,০০০ টাকা অতিরিক্ত মূলধন আনেন এবং ব্যক্তিগত প্রয়োজনে কারবার থেকে ৩০,০০০ টাকা উত্তোলন করেন।

[করণীয় প্রশ্ন]:
ক) জনাব সোলায়মানের প্রারম্ভিক মূলধনের পরিমাণ নির্ণয় কর।
খ) সমাপনী মূলধনের পরিমাণ নির্ণয় কর।
গ) ২০২৩ সালে জনাব সোলায়মানের ব্যবসায়ের লাভ বা ক্ষতির পরিমাণ নিরূপণ কর।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) প্রারম্ভিক মূলধনের পরিমাণ:**
প্রারম্ভিক মূলধন = প্রারম্ভিক মোট সম্পদ - প্রারম্ভিক মোট দায়
= ২,৫০,০০০ - ৭০,০০০ = **১,৮০,০০০ টাকা**।

**খ) সমাপনী মূলধনের পরিমাণ:**
সমাপনী মূলধন = সমাপনী মোট সম্পদ - সমাপনী মোট দায়
= ৩,২০,০০০ - ৬০,০০০ = **২,৬০,০০০ টাকা**।

**গ) লাভ বা ক্ষতি নির্ণয়:**
সূত্র: `লাভ/ক্ষতি = (সমাপনী মূলধন + উত্তোলন) - (প্রারম্ভিক মূলধন + অতিরিক্ত মূলধন)`
= (২,৬০,০০০ + ৩০,০০০) - (১,৮০,০০০ + ২০,০০০)
= ২,৯০,০০০ - ২,০০,০০০
= **+ ৯০,০০০ টাকা** (যেহেতু ধনাত্মক মান এসেছে, সুতরাং এটি **নিট লাভ**)।$lesson$,
        5
    );

