-- ==================== seed_chapter_4_capital_revenue.sql ====================
-- ============================================================
-- Complete Educational Lessons & 30 Practice Questions
-- For Chapter 4: মূলধন ও মুনাফাজাতীয় লেনদেন (Capital & Revenue Transactions)
-- Class 9 Bangladesh Curriculum - Accounting (হিসাববিজ্ঞান)
-- Includes:
-- 1. Concept, Time Horizon & 3 Distinct Characteristics (Table)
-- 2. Capital Receipts, Capital Gains/Income & Capital Expenditures
-- 3. Revenue Receipts/Income, Revenue Expenditures & Deferred Revenue Expenditure
-- 4. Tricky Board Traps (Old Asset Sale Gain, Registration Fees, Overhaul Costs)
-- 5. Creative Questions 01 & 02 (Classification & Mathematical Calculation)
-- 6. Creative Questions 03, 04, 05 (Asset Sale Math, Self-Assessment & 5 Golden Tips)
-- 7. 30 Interactive Practice Questions (6 Checkpoint Rounds of 5 questions)
-- ============================================================

DO $$
DECLARE
    v_ch4_id UUID;
BEGIN
    -- 1. Find Chapter 4 ID strictly by order_index = 4
    SELECT id INTO v_ch4_id 
    FROM chapters 
    WHERE order_index = 4 
    LIMIT 1;

    IF v_ch4_id IS NULL THEN
        RAISE NOTICE 'Chapter 4 (মূলধন ও মুনাফা) not found. Please run seed_accounting.sql first.';
        RETURN;
    END IF;

    -- Clean previous lessons and questions for Chapter 4
    DELETE FROM lessons WHERE chapter_id = v_ch4_id;
    DELETE FROM exam_questions WHERE chapter_id = v_ch4_id;

    -- ============================================================
    -- LESSON 1: মূলধন ও মুনাফাজাতীয় লেনদেনের মৌলিক ধারণা ও বৈশিষ্ট্য
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch4_id,
        $lesson$📌 পাঠ ১: মূলধন ও মুনাফাজাতীয় লেনদেনের সহজ ধারণা ও ৩টি পার্থক্যকারী বৈশিষ্ট্য

ব্যবসায়ের সঠিক আর্থিক ফলাফল (লাভ-ক্ষতি) এবং প্রকৃত আর্থিক অবস্থা জানার জন্য প্রতিটি লেনদেনকে সঠিকভাবে **"মূলধন জাতীয়"** কিংবা **"মুনাফাজাতীয়"** হিসেবে চিহ্নিত করা অপরিহার্য।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ মূলধন বনাম মুনাফাজাতীয় লেনদেন চিহ্নিতকরণের ৩টি মাপকাঠি:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━

| তুলনার মাপকাঠি | মূলধন জাতীয় লেনদেন (Capital) | মুনাফাজাতীয় লেনদেন (Revenue) |
| :--- | :--- | :--- |
| **১. সুবিধার মেয়াদকাল (Benefit Period)** | দীর্ঘমেয়াদি (১ বছরের বেশি সময় সুবিধা পাওয়া যায়) | স্বল্পমেয়াদি (১ বছরের মধ্যে সুবিধা নিঃশেষ হয়ে যায়) |
| **২. পুনরাবৃত্তির প্রকৃতি (Recurrence)** | অনিয়মিত ও অনাবৃত (মাঝে মাঝে ঘটে) | নিয়মিত ও পৌনঃপুনিক (বারবার ঘটে) |
| **৩. টাকার অঙ্ক (Amount Size)** | তুলনামূলকভাবে বড় অঙ্কের টাকা | তুলনামূলকভাবে ছোট বা মাঝারি অঙ্কের টাকা |

────────────────────────────
■ বাস্তব উদাহরণ:
────────────────────────────
• কারবারের জন্য একটি কম্পিউটার ক্রয় ৫০,০০০ টাকা ➔ **মূলধন জাতীয় লেনদেন** (কারণ এটি অনিয়মিত, বড় অঙ্ক এবং বহু বছর সেবা দেবে)।
• কম্পিউটার পরিচালনাকারীর মাসিক বেতন ৫,০০০ টাকা ➔ **মুনাফাজাতীয় লেনদেন** (কারণ এটি প্রতি মাসে নিয়মিত পরিশোধ করতে হয়)।$lesson$,
        1
    );

    -- ============================================================
    -- LESSON 2: মূলধন জাতীয় প্রাপ্তি, আয় ও মূলধন জাতীয় ব্যয়
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch4_id,
        $lesson$📌 পাঠ ২: মূলধন জাতীয় প্রাপ্তি, মূলধন জাতীয় আয় ও ব্যয়

মূলধন জাতীয় লেনদেনকে প্রধানত দুটি ভাগে ভাগ করা হয়:
১. মূলধন জাতীয় প্রাপ্তি ও আয়
২. মূলধন জাতীয় ব্যয়

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. মূলধন জাতীয় প্রাপ্তি (Capital Receipts):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
যেসব প্রাপ্তি অনিয়মিত, টাকার অঙ্ক বড় এবং দীর্ঘমেয়াদে সুবিধা দেয়:
• মালিক কর্তৃক ব্যবসায়ে আনীত মূলধন
• ব্যাংক বা অন্য কোনো আর্থিক প্রতিষ্ঠান থেকে ঋণ গ্রহণ
• স্থায়ী সম্পদ (যেমন: জমি, দালানকোঠা, যন্ত্রপাতি বা আসবাবপত্র) বিক্রয় করে প্রাপ্ত মোট নগদ টাকা

────────────────────────────
■ মূলধন জাতীয় আয় (Capital Gain / Income):
────────────────────────────
মূলধন জাতীয় প্রাপ্তি এবং মূলধন জাতীয় আয়ের মধ্যে সূক্ষ্ম কিন্তু গুরুত্বপূর্ণ পার্থক্য রয়েছে:
`মূলধন জাতীয় আয় = স্থায়ী সম্পদ বিক্রয়মূল্য - স্থায়ী সম্পদের বইমূল্য (Book Value)`
• উদাহরণ: ৩০,০০০ টাকার আসবাবপত্র ৩৫,০০০ টাকায় বিক্রয় করা হলো।
  - এখানে পুরো ৩৫,০০০ টাকা হলো **মূলধন জাতীয় প্রাপ্তি**।
  - কিন্তু অতিরিক্ত লাভ (৩৫,০০০ - ৩০,০০০) = **৫,০০০ টাকা হলো মূলধন জাতীয় আয়**।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. মূলধন জাতীয় ব্যয় (Capital Expenditure):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
যেসব ব্যয়ের ফল দীর্ঘমেয়াদে ভোগ করা যায় এবং যা প্রতিষ্ঠানের উৎপাদন ক্ষমতা বৃদ্ধি করে:
১. স্থায়ী সম্পদ অর্জন (জমি, দালান, যন্ত্রপাতি, গাড়ি, অফিস সরঞ্জাম ক্রয়)।
২. **স্থায়ী সম্পদ ক্রয়ের আনুষঙ্গিক সমস্ত প্রাথমিক খরচ:**
   • যন্ত্রপাতি আমদানির জাহাজ ভাড়া, শুল্ক ও পরিবহন খরচ
   • যন্ত্রপাতি সংস্থাপন ব্যয় (Installation Cost)
   • জমি বা দালানকোঠা ক্রয়ের রেজিস্ট্রেশন ফি ও দলিলের আইনি খরচ
   • পুরাতন মোটরগাড়ির বড় ধরনের ওভারহোলিং বা পুনঃসংস্কার ব্যয়$lesson$,
        2
    );

    -- ============================================================
    -- LESSON 3: মুনাফাজাতীয় প্রাপ্তি, আয়, ব্যয় ও বিলম্বিত ব্যয়
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch4_id,
        $lesson$📌 পাঠ ৩: মুনাফাজাতীয় আয়, মুনাফাজাতীয় ব্যয় ও বিলম্বিত মুনাফাজাতীয় ব্যয়

কারবারের দৈনন্দিন কার্যক্রম চালু রাখা এবং পণ্য উৎপাদনের সাথে মুনাফাজাতীয় লেনদেন জড়িত।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. মুনাফাজাতীয় প্রাপ্তি ও আয়:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• **মুনাফাজাতীয় প্রাপ্তি:** চলতি, বিগত বা অগ্রিম মিলিয়ে যে কোনো নিয়মিত উৎস থেকে প্রাপ্ত মোট টাকা।
• **মুনাফাজাতীয় আয়:** প্রাপ্তির মধ্য থেকে **শুধুমাত্র চলতি নির্দিষ্ট হিসাবকালের অংশটুকু**।
• উদাহরণ: পণ্য বিক্রয়লব্ধ অর্থ, কমিশন প্রাপ্তি, বাড়ি ভাড়া প্রাপ্তি, বিনিয়োগের সুদ, প্রাপ্ত বাট্টা।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. মুনাফাজাতীয় ব্যয় (Revenue Expenditure):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
ব্যবসায়ের দৈনন্দিন পরিচালন খরচ যা এক বছরের মধ্যে নিঃশেষ হয়ে যায়:
• কাঁচামাল বা পণ্য ক্রয় ও ক্রয় পরিবহন
• কর্মকর্তা-কর্মচারীর বেতন ও কারখানা শ্রমিকের মজুরি
• দোকান ভাড়া, বিদ্যুৎ ও গ্যাস বিল
• বিজ্ঞাপন ও প্রচার খরচ
• স্থায়ী সম্পদের ব্যবহারজনিত সাধারণ অবচয় ও খুচরা মেরামত খরচ

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ৩. বিলম্বিত মুনাফাজাতীয় ব্যয় (Deferred Revenue Expenditure):
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
কিছু ব্যয় প্রকৃতিগতভাবে মুনাফাজাতীয় হলেও যার সুবিধার পরিধি একাধিক বছর ধরে বিস্তৃত থাকে:
১. **নতুন পণ্যের বাজারজাতকরণের জন্য অস্বাভাবিক বড় অঙ্কের বিজ্ঞাপন খরচ** (যেমন: ৫ বছরের জন্য ৫০,০০০ টাকার প্রচারণা)।
২. **ব্যবসায়ের কারখানা বা প্রধান কার্যালয় সুবিধাজনক স্থানে স্থানান্তরের ব্যয়**।
৩. **কোম্পানি গঠনের প্রাথমিক খরচাবলী (Preliminary Expenses)**।
৪. **নতুন পণ্য উদ্ভাবনের দীর্ঘমেয়াদি গবেষণা ও উন্নয়ন ব্যয়**।$lesson$,
        3
    );

    -- ============================================================
    -- LESSON 4: বোর্ড পরীক্ষার বিভ্রান্তিকর দফাসমূহ (বোর্ড ফাঁদ)
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch4_id,
        $lesson$📌 পাঠ ৪: বোর্ড পরীক্ষার বিভ্রান্তিকর দফাসমূহ ও বিশেষ ফাঁদ

বোর্ড পরীক্ষার প্রশ্নে এমন কিছু লেনদেন দেওয়া থাকে যা দেখতে সাধারণ খরচের মতো মনে হলেও মূলধন জাতীয় ব্যয়ের অন্তর্ভুক্ত হয়:

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ১. স্থায়ী সম্পদের সংস্থাপন ও পরিবহন ব্যয়:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• কোনো স্থায়ী সম্পদ ক্রয়ের পর তা চালু করার পূর্ব পর্যন্ত যাবতীয় খরচ মূলধন জাতীয়।
• যেমন: নতুন এসি কেনা ৬০,০০০ টাকা এবং তা দেওয়ালে ফিটিং করার খরচ ৩,০০০ টাকা।
  ➔ এখানে সংস্থাপন খরচ ৩,০০০ টাকা মুনাফাজাতীয় খরচ নয়; এটি **মূলধন জাতীয় ব্যয়** (এসির মোট ক্রয়মূল্য হবে ৬৩,০০০ টাকা)।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ২. রেজিস্ট্রেশন ও আইনি খরচ:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• জমি ক্রয়ের রেজিস্ট্রেশন ও নামজারি ফি ৫০,০০০ টাকা ➔ এটি **মূলধন জাতীয় ব্যয়** (জমির মূল্যের সাথে যোগ হবে)।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ ৩. পুরাতন সম্পদ বনাম নতুন সম্পদ মেরামত:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
• পুরাতন ব্যবহৃত গাড়ি ক্রয় করে তা ব্যবহারের উপযোগী করার জন্য ইঞ্জিন মেরামত ২০,০০০ টাকা ➔ **মূলধন জাতীয় ব্যয়**।
• কিন্তু গাড়িটি চালু হওয়ার পর নিয়মিত তেলের খরচ বা সাধারণ সার্ভিসিং ➔ **মুনাফাজাতীয় ব্যয়**।

────────────────────────────
■ দ্রুত মনে রাখার গোল্ডেন ছক:
────────────────────────────
| লেনদেন | শ্রেণি | কারণ |
| :--- | :---: | :--- |
| ১. মেশিন আমদানির শুল্ক | **মূলধন জাতীয়** | মেশিন ক্রয়ের সাথে সরাসরি যুক্ত প্রাথমিক খরচ |
| ২. নিয়মিত পণ্য আমদানির শুল্ক | **মুনাফাজাতীয়** | বিক্রয়ের উদ্দেশ্যে পণ্য আমদানির খরচ |
| ৩. অফিস ভবনে নতুন ফ্লোর নির্মাণ | **মূলধন জাতীয়** | ভবনের স্থায়ী আয়তন ও ক্ষমতা বৃদ্ধি |
| ৪. অফিস ভবনে নিয়মিত চুনকাম ও রঙ | **মুনাফাজাতীয়** | নিয়মিত রক্ষণাবেক্ষণ খরচ |$lesson$,
        4
    );

    -- ============================================================
    -- LESSON 5: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২
    -- ============================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch4_id,
        $lesson$📌 পাঠ ৫: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২ (পূর্ণাঙ্গ সমাধান)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০১ (মূলধন ও মুনাফাজাতীয় চিহ্নিতকরণ ও মোট পরিমাণ)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব জামালের মেসার্স কর্ণফুলী ট্রেডার্সের ২০২৩ সালের লেনদেনসমূহ:
• জানু ১: ব্যবসায়ের জন্য নতুন যন্ত্রপাতি ক্রয় ১,২০,০০০ টাকা।
• জানু ৫: যন্ত্রপাতি পরিবহনের জন্য ট্রাক ভাড়া প্রদান ৫,০০০ টাকা।
• জানু ১০: যন্ত্রপাতির সংস্থাপন ব্যয় প্রদান ৮,০০০ টাকা।
• জানু ১৫: বিক্রয়ের উদ্দেশ্যে পণ্য ক্রয় ৭০,০০০ টাকা।
• জানু ২০: ৫ বছরের জন্য বড় ধরনের বিশেষ বিজ্ঞাপন ব্যয় ৫০,০০০ টাকা।
• জানু ২৫: কর্মচারীদের বেতন প্রদান ১৫,০০০ টাকা।
• জানু ২৮: বিদ্যুৎ ও অফিস বিল প্রদান ৪,০০০ টাকা।

[করণীয় প্রশ্ন]:
ক) জনাব জামালের মোট মূলধন জাতীয় ব্যয়ের পরিমাণ নির্ণয় কর।
খ) উক্ত প্রতিষ্ঠানের মোট মুনাফাজাতীয় ব্যয়ের পরিমাণ কত?
গ) বিলম্বিত মুনাফাজাতীয় ব্যয়ের পরিমাণ ও তার বৈশিষ্ট্য ব্যাখ্যা কর।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) মোট মূলধন জাতীয় ব্যয়ের পরিমাণ:**
| বিবরণ | টাকা |
| :--- | :---: |
| যন্ত্রপাতি ক্রয় | ১,২০,০০০ |
| যন্ত্রপাতি পরিবহন খরচ | ৫,০০০ |
| যন্ত্রপাতি সংস্থাপন ব্যয় | ৮,০০০ |
| **মোট মূলধন জাতীয় ব্যয়** | **১,৩৩,০০০** |
*(নোট: স্থায়ী সম্পদ ব্যবহারের উপযোগী করার পূর্ব পর্যন্ত সমস্ত খরচ মূলধন জাতীয় হিসেবে যন্ত্রপাতির মূল্যের সাথে যুক্ত হয়।)*

**খ) মোট মুনাফাজাতীয় ব্যয়ের পরিমাণ:**
| বিবরণ | টাকা |
| :--- | :---: |
| পণ্য ক্রয় | ৭০,০০০ |
| কর্মচারীদের বেতন | ১৫,০০০ |
| বিদ্যুৎ ও অফিস বিল | ৪,০০০ |
| **মোট মুনাফাজাতীয় ব্যয়** | **৮৯,০০০** |

**গ) বিলম্বিত মুনাফাজাতীয় ব্যয়ের পরিমাণ ও বৈশিষ্ট্য:**
• বিলম্বিত মুনাফাজাতীয় ব্যয়ের পরিমাণ = **৫০,০০০ টাকা** (৫ বছরের বিজ্ঞাপন ব্যয়)।
• **বৈশিষ্ট্য:**
  ১. ব্যয়টি দেখতে মুনাফাজাতীয় হলেও এর সুবিধা ৫ বছর ধরে পাওয়া যাবে।
  ২. চলতি বছরে ১ বছরের অংশ (১০,০০০ টাকা) বিশদ আয় বিবরণীতে খরচ হিসেবে দেখানো হবে এবং বাকি ৪০,০০০ টাকা আর্থিক অবস্থার বিবরণীতে 'অবাস্তব সম্পদ' হিসেবে প্রদর্শিত হবে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০২ (স্থায়ী সম্পদ বিক্রয় ও মূলধন জাতীয় আয় নির্ণয়)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক]:
জনাব রশীদের একটি পুরাতন ফটোকপি মেশিন ছিল যার বইমূল্য (Book Value) ছিল ৪০,০০০ টাকা। তিনি মেশিনটি নতুন মডেল কেনার উদ্দেশ্যে ৪৫,০০০ টাকায় নগদে বিক্রয় করলেন। একই মাসে তিনি ৫০,০০০ টাকার মূলধন বিনিয়োগ করেন এবং ব্যাংক হতে ৮০,০০০ টাকা ঋণ গ্রহণ করেন।

[করণীয় প্রশ্ন]:
ক) জনাব রশীদের মূলধন জাতীয় আয়ের পরিমাণ নির্ণয় কর।
খ) মোট মূলধন জাতীয় প্রাপ্তির পরিমাণ নির্ণয় কর।
গ) মূলধন জাতীয় প্রাপ্তি ও মূলধন জাতীয় আয়ের মধ্যে পার্থক্য সুস্পষ্ট কর।

────────────────────────────
[উত্তর ও পূর্ণাঙ্গ সমাধান]:

**ক) মূলধন জাতীয় আয়ের পরিমাণ:**
সূত্র: `মূলধন জাতীয় আয় = বিক্রয়মূল্য - বইমূল্য`
= ৪৫,০০০ - ৪০,০০০ = **৫,০০০ টাকা**।

**খ) মোট মূলধন জাতীয় প্রাপ্তির পরিমাণ:**
| বিবরণ | টাকা |
| :--- | :---: |
| মূলধন বিনিয়োগ | ৫০,০০০ |
| ব্যাংক ঋণ গ্রহণ | ৮০,০০০ |
| পুরাতন ফটোকপি মেশিন বিক্রয়লব্ধ মোট অর্থ | ৪৫,০০০ |
| **মোট মূলধন জাতীয় প্রাপ্তি** | **১,৭৫,০০০** |

**গ) মূলধন জাতীয় প্রাপ্তি ও আয়ের পার্থক্য:**
১. ফটোকপি মেশিন বিক্রয় করে হাতে মোট যে ৪৫,০০০ টাকা এসেছে তা হলো **মূলধন জাতীয় প্রাপ্তি**।
২. কিন্তু ৪৫,০০০ টাকার মধ্যে মেশিনের মূল্যের চেয়ে যে অতিরিক্ত ৫,০০০ টাকা মুনাফা বা লাভ হয়েছে, কেবল সেই ৫,০০০ টাকাই হলো **মূলধন জাতীয় আয়**।
৩. সুতরাং সকল মূলধন জাতীয় আয়ই প্রাপ্তির অংশ, কিন্তু সকল প্রাপ্তি আয় নয়।$lesson$,
        5
    );

