        v_ch4_id,
        $lesson$📌 পাঠ ৬: সৃজনশীল প্রশ্ন ০৩, ০৪, ০৫ ও ফাইনাল ৫টি গোল্ডেন টিপস

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৩ (ভুল শ্রেণিবিভাগের আর্থিক ফলাফল)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[উদ্দীপক ও প্রশ্ন]:
কোনো হিসাবরক্ষক যদি নতুন মেশিনের সংস্থাপন ব্যয় ১০,০০০ টাকাকে ভুলবশত মুনাফাজাতীয় খরচ হিসেবে লিখে ফেলেন, তবে কারবারের আর্থিক ফলাফলে কী বিপর্যয় ঘটবে?
[উত্তর]:
১. **লাভের ওপর প্রভাব:** মুনাফাজাতীয় খরচ ১০,০০০ টাকা বেশি দেখানোর ফলে চলতি বছরের নিট লাভ ১০,০০০ টাকা কম (Understated) দেখানো হবে।
২. **সম্পদের ওপর প্রভাব:** আর্থিক অবস্থার বিবরণীতে মেশিনের মোট মূল্য ১০,০০০ টাকা কম দেখানো হবে, যার ফলে কারবারের প্রকৃত সম্পদ ও আর্থিক অবস্থা ভুলভাবে উপস্থাপিত হবে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৪ (বিলম্বিত ব্যয় অবলোপনের নিয়ম)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
কারখানা স্থানান্তর ব্যয় ৩০,০০০ টাকা ৩ বছরে অবলোপন করার সিদ্ধান্ত হলে প্রতি বছর কত টাকা চার্জ হবে?
[উত্তর]:
প্রতি বছরের মুনাফাজাতীয় অংশ = ৩০,০০০ ÷ ৩ = **১০,০০০ টাকা** (যা চলতি বছরের আয় বিবরণীতে ব্যয় হিসেবে যাবে)।
অবশিষ্ট ২০,০০০ টাকা চলতি বছরের উদ্বৃত্তপত্রে অসমন্বিত সম্পদ হিসেবে প্রদর্শিত হবে।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ সৃজনশীল প্রশ্ন - ০৫ (মেয়ের আত্মমূল্যায়নের জন্য - Self Assessment)
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
[প্রশ্ন]:
জমি ক্রয়ের জন্য আইনি ফি ১০,০০০ টাকা দেওয়া হলো। এটি কোন শ্রেণির ব্যয় এবং কেন?
[সমাধান সংক্ষেপ]:
এটি **মূলধন জাতীয় ব্যয়**। কারণ আইনি ফি প্রদান ছাড়া জমির মালিকানা অর্জন অসম্ভব। স্থায়ী সম্পদ ক্রয়ের সরাসরি সহযোগী যেকোনো খরচ স্থায়ী সম্পদের সাথে যোগ হয়ে মূলধন জাতীয় ব্যয়ে রূপান্তরিত হয়।

━━━━━━━━━━━━━━━━━━━━━━━━━━━━
■ 📝 আপনার মেয়ের জন্য চূড়ান্ত ৫টি গোল্ডেন টিপস:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━
১. **স্থায়ী সম্পদের সহযোগী সব খরচ মূলধন জাতীয়:** সংস্থাপন, আমদানি শুল্ক, পরিবহন, রেজিস্ট্রেশন—সবই মূলধন জাতীয়।
২. **বিলম্বিত ব্যয় চেনার উপায়:** বড় বিজ্ঞাপন, কারখানা স্থানান্তর বা প্রাথমিক খরচ দেখলেই সেটি 'বিলম্বিত মুনাফাজাতীয় ব্যয়'।
৩. **প্রাপ্তি বনাম আয়:** বিক্রয় করে পাওয়া পুরো টাকা হলো প্রাপ্তি; আর তার মধ্য থেকে লাভ বা চলতি বছরের অংশ হলো আয়।
৪. **নিয়মিত মেরামত বনাম বড় মেরামত:** গাড়ির চাকা পাংচার সাড়ানো মুনাফাজাতীয়; কিন্তু গাড়ির সম্পূর্ণ ইঞ্জিন পরিবর্তন মূলধন জাতীয়।
৫. **পণ্য বনাম স্থায়ী সম্পদ:** বিক্রয়ের উদ্দেশ্যে কেনা পণ্য সবসময় মুনাফাজাতীয়; ব্যবহারের উদ্দেশ্যে কেনা আসবাব বা মেশিন মূলধন জাতীয়।$lesson$,
        6
    );

