-- ==================== seed_chapter_6_journal.sql ====================
-- ==============================================================================
-- CHAPTER 6: জাবেদা (Journal) - COMPREHENSIVE MASTERCLASS SEED SCRIPT
-- ==============================================================================
-- Specially enriched for deep conceptual clarity on Debit & Credit:
-- • 30+ real-life practical transactions with classification, reason & journal entry
-- • Merchandise vs Assets distinctions (Installation costs, repairs)
-- • Banking dilemmas (Personal vs Business withdrawal, direct deposit, charges)
-- • Accrual & Advance adjustments (Outstanding expenses, prepaid rent, accrued income)
-- • Discounts (Trade vs Cash discount full settlement)
-- • Free distribution, drawings of goods & abnormal losses (Fire, Insurance claim)
-- • Special Journals, Creative Questions (CQs) with full solutions, and 30 MCQs.
-- ==============================================================================

DO $$
DECLARE
    v_ch6_id UUID;
BEGIN
    -- Find Chapter 6 ID strictly by order_index = 6
    SELECT id INTO v_ch6_id 
    FROM chapters 
    WHERE order_index = 6 
    LIMIT 1;

    IF v_ch6_id IS NULL THEN
        RAISE NOTICE 'Chapter 6 (জাবেদা) not found. Skipping.';
        RETURN;
    END IF;

    -- Update chapter title
    UPDATE chapters 
    SET title_bn = '৬ষ্ঠ অধ্যায়: জাবেদা (Journal)',
        title_en = 'Chapter 6: Journal'
    WHERE id = v_ch6_id;

    -- Clean previous lessons and questions for Chapter 6
    DELETE FROM lessons WHERE chapter_id = v_ch6_id;
    DELETE FROM exam_questions WHERE chapter_id = v_ch6_id;

    -- ==========================================================================
    -- LESSON 1: জাবেদার ধারণা, ছক ও ডেবিট-ক্রেডিট নির্ণয়ের জাদুকরী রুলস
    -- ==========================================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch6_id,
        $lesson$# পাঠ ১: জাবেদার ধারণা, ছক ও ডেবিট-ক্রেডিট নির্ণয়ের জাদুকরী রুলস

## ১. জাবেদা কী? (Concept of Journal)
ব্যবসায়ের কোনো আর্থিক ঘটনা ঘটার সাথে সাথে তারিখের ক্রমানুসারে ডেবিট ও ক্রেডিট পক্ষ বিশ্লেষণ করে সংক্ষিপ্ত ব্যাখ্যাসহ সর্বপ্রথম যে বইতে লেখা হয়, তাকে **জাবেদা (Journal)** বলে।
- **উৎপত্তি:** ফরাসি শব্দ **'Jour'** (জার) থেকে Journal শব্দটির উৎপত্তি, যার অর্থ হলো **'দিন (Day)'**।
- **উপাধি:** জাবেদাকে বলা হয় হিসাবের **'প্রাথমিক বই'** বা **'দৈনিক বই (Book of Original Entry)'**।

---

## ২. ডেবিট ও ক্রেডিট নির্ণয়ের আধুনিক গোল্ডেন রুলস (Golden Rules)
হিসাববিজ্ঞানের আধুনিক সমীকরণ অনুযায়ী হিসাব প্রধানত ৫ প্রকার:
```
+--------------------------------------------------------------------------+
| হিসাবের শ্রেণি              | বৃদ্ধি পেলে (+)     | হ্রাস পেলে (-)      |
+--------------------------------------------------------------------------+
| ১. সম্পদ (Assets - A)        | ডেবিট (Debit)      | ক্রেডিট (Credit)    |
| ২. ব্যয় (Expenses - E)      | ডেবিট (Debit)      | ক্রেডিট (Credit)    |
| ৩. দায় (Liabilities - L)    | ক্রেডিট (Credit)    | ডেবিট (Debit)      |
| ৪. মালিকানা স্বত্ব (Equity - E)| ক্রেডিট (Credit)    | ডেবিট (Debit)      |
| ৫. আয় (Revenue - R)         | ক্রেডিট (Credit)    | ডেবিট (Debit)      |
+--------------------------------------------------------------------------+
```

### 💡 শিক্ষার্থীদের মনে রাখার ম্যাজিক টেকনিক:
> **"সবাই" সূত্র:**  
> - **'স' (সম্পদ) ও 'ব্য' (ব্যয়):** বাড়লে **ডেবিট**, কমলে **ক্রেডিট**।  
> - **'দা' (দায়), 'মা' (মালিকানা স্বত্ব), 'আ' (আয়):** বাড়লে **ক্রেডিট**, কমলে **ডেবিট**।

---

## ৩. সাধারণ জাবেদার প্রমিত ৫-কলাম ছক (Standard 5-Column Format)

| তারিখ | হিসাবের শিরোনাম ও ব্যাখ্যা | খতিয়ান পৃষ্ঠা (L.F.) | ডেবিট টাকা (Dr.) | ক্রেডিট টাকা (Cr.) |
| :---: | :--- | :---: | :---: | :---: |
| ২০২৩ মে ১ | **নগদান হিসাব**<br>    **মূলধন হিসাব**<br>*(যেহেতু নগদ অর্থ নিয়ে ব্যবসায় শুরু করা হলো)* | ১<br>১০ | ৫০,০০০<br>— | —<br>৫০,০০০ |

### জাবেদা লেখার ৪টি অলঙ্ঘনীয় নিয়ম:
১. **ডেবিট হিসাবটি** বাম ঘেঁষে উপরে লিখতে হয়।
২. **ক্রেডিট হিসাবটি** নিচে একটু ডান দিকে সরিয়ে (Indent করে) লিখতে হয়।
৩. প্রতিটি দাখিলার নিচে প্রথম বন্ধনীতে `(যেহেতু ...)` দিয়ে লেনদেনটির কারণ/ব্যাখ্যা লেখা বাধ্যতামূলক।
৪. বিবরণ কলামে একটি লেনদেন শেষ হলে নিচে একটি দাগ টেনে দিতে হয় (টাকার ঘরে দাগ পড়বে না)।$lesson$,
        1
    );

    -- ==========================================================================
    -- LESSON 2: পণ্য ক্রয়, বিক্রয়, ফেরত ও উত্তোলন সংক্রান্ত লেনদেন
    -- ==========================================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        v_ch6_id,
        $lesson$# পাঠ ২: পণ্য ক্রয়, বিক্রয়, ফেরত ও উত্তোলন সংক্রান্ত লেনদেনের মাস্টারক্লাস

ব্যবসায়ের সবচেয়ে বেশি লেনদেন হয় পণ্য কেনা-বেচা নিয়ে। এখানে মনে রাখতে হবে: **পণ্য, মাল বা দ্রব্য নামে হিসাববিজ্ঞানে কোনো হিসাব খোলা হয় না!** পণ্য কিনলে 'ক্রয় হিসাব' এবং বেচলে 'বিক্রয় হিসাব' লিখতে হয়।

---

## ১. পণ্য ক্রয় সংক্রান্ত লেনদেনের বিশ্লেষণ

### লেনদেন ১: নগদে পণ্য ক্রয় ২০,০০০ টাকা
- **জড়িত দুটি পক্ষ:** ক্রয় হিসাব (ব্যয়) এবং নগদান হিসাব (সম্পদ)।
- **কারণ:** পণ্য ক্রয়ে ব্যবসায়ের খরচ বেড়েছে এবং নগদ টাকা কমেছে।
- **জাবেদা:**
  - **ক্রয় হিসাব ডেবিট ২০,০০০** (ব্যয় বৃদ্ধি)
  - **নগদান হিসাব ক্রেডিট ২০,০০০** (সম্পদ হ্রাস)

### লেনদেন ২: চেকে পণ্য ক্রয় ১৫,০০০ টাকা
- **জাবেদা:**
  - **ক্রয় হিসাব ডেবিট ১৫,০০০** (ব্যয় বৃদ্ধি)
  - **ব্যাংক হিসাব ক্রেডিট ১৫,০০০** (ব্যাংক সম্পদ হ্রাস)

### লেনদেন ৩: জনাব রহিমের নিকট হতে ধারে পণ্য ক্রয় ২৫,০০০ টাকা
- **যুক্তি:** ব্যক্তির নাম আছে কিন্তু নগদ বা চেকের কথা বলা নেই, তাই এটি শতভাগ ধারে লেনদেন। সরবরাহকারী হলো পাওনাদার।
- **জাবেদা:**
  - **ক্রয় হিসাব ডেবিট ২৫,০০০** (ব্যয় বৃদ্ধি)
  - **প্রদেয় হিসাব (রহিম) ক্রেডিট ২৫,০০০** (দায় বৃদ্ধি)

### লেনদেন ৪: ফরমায়েশ বা অর্ডার দেওয়া হলো ১০,০০০ টাকার পণ্য ক্রয়ের জন্য
- **উত্তর:** **এটি কোনো লেনদেন নয়!** কারণ পণ্যের বা অর্থের কোনো আদান-প্রদান হয়নি। এর কোনো জাবেদা হবে না।

---

## ২. পণ্য বিক্রয় সংক্রান্ত লেনদেনের বিশ্লেষণ

### লেনদেন ৫: নগদে পণ্য বিক্রয় ৩০,০০০ টাকা
- **জাবেদা:**
  - **নগদান হিসাব ডেবিট ৩০,০০০** (নগদ সম্পদ বৃদ্ধি)
  - **বিক্রয় হিসাব ক্রেডিট ৩০,০০০** (ব্যবসায়ের আয় বৃদ্ধি)

### লেনদেন ৬: করিমের নিকট ধারে বিক্রয় ৪০,০০০ টাকা
- **জড়িত পক্ষ:** গ্রাহক বা প্রাপ্য হিসাব (দেনাদার) এবং বিক্রয় হিসাব।
- **জাবেদা:**
  - **প্রাপ্য হিসাব (করিম) ডেবিট ৪০,০০০** (সম্পদ বৃদ্ধি)
  - **বিক্রয় হিসাব ক্রেডিট ৪০,০০০** (আয় বৃদ্ধি)

### লেনদেন ৭: মোবাইল ব্যাংকিং (বিকাশ/নগদ) বা ক্রেডিট কার্ডে পণ্য বিক্রয় ১২,০০০ টাকা
- **জাবেদা:**
  - **ব্যাংক হিসাব / নগদ সমতুল্য ডেবিট ১২,০০০** (সম্পদ বৃদ্ধি)
  - **বিক্রয় হিসাব ক্রেডিট ১২,০০০** (আয় বৃদ্ধি)

---

## ৩. পণ্য ফেরত ও বিশেষ লেনদেনসমূহ

### লেনদেন ৮: রহিমকে ক্রয়কৃত নষ্ট পণ্য ফেরত পাঠানো হলো ২,০০০ টাকা (বহিঃফেরত)
- **যুক্তি:** পাওনাদারের কাছে পণ্য পাঠালে পাওনাদারের প্রতি দায় কমে এবং মোট ক্রয় খরচও কমে।
- **জাবেদা:**
  - **প্রদেয় হিসাব (রহিম) ডেবিট ২,০০০** (দায় হ্রাস)
  - **ক্রয় ফেরত হিসাব ক্রেডিট ২,০০০** (ব্যয় হ্রাস)

### লেনদেন ৯: গ্রাহক করিম পণ্য ফেরত দিল ৩,০০০ টাকা (আন্তঃফেরত)
- **জাবেদা:**
  - **বিক্রয় ফেরত হিসাব ডেবিট ৩,০০০** (আয় হ্রাস)
  - **প্রাপ্য হিসাব (করিম) ক্রেডিট ৩,০০০** (সম্পদ হ্রাস)

### লেনদেন ১০: মালিক ব্যক্তিগত ব্যবহারের জন্য কারবার থেকে ৫,০০০ টাকার পণ্য উত্তোলন করলেন
- **অত্যন্ত গুরুত্বপূর্ণ ট্রিক:** মালিক পণ্য নিলে ক্রয়মূল্যে হিসাব হ্রাস পায়। কখনো বিক্রয় হিসাব ক্রেডিট হবে না!
- **জাবেদা:**
  - **উত্তোলন হিসাব ডেবিট ৫,০০০** (মালিকানা স্বত্ব হ্রাস)
  - **ক্রয় হিসাব ক্রেডিট ৫,০০০** (ব্যবসায়ের পণ্য ক্রয় ব্যয় হ্রাস)

### লেনদেন ১১: বিজ্ঞাপনের উদ্দেশ্যে বিনামূল্যে ৪,০০০ টাকার পণ্য বিতরণ করা হলো
- **যুক্তি:** পণ্য দিলে প্রচার বাড়ে (বিজ্ঞাপন খরচ) এবং গোডাউনের ক্রয়কৃত পণ্য কমে যায়।
- **জাবেদা:**
  - **বিজ্ঞাপন হিসাব ডেবিট ৪,০০০** (ব্যয় বৃদ্ধি)
  - **ক্রয় হিসাব ক্রেডিট ৪,০০০** (ক্রয়কৃত পণ্যের ব্যয় হ্রাস)$lesson$,
        2
    );

