        $lesson$# পাঠ ৩: সম্পদ ক্রয় বনাম ব্যয়, সংস্থাপন ব্যয় ও ব্যাংকিং লেনদেনের প্যাঁচ

শিক্ষার্থীরা সবচেয়ে বেশি ভুল করে **"পণ্য ক্রয়"** এবং **"স্থায়ী সম্পদ ক্রয়"** এর মধ্যে গুলিয়ে ফেলে। এই পাঠে সেই প্যাঁচগুলো আজীবনের জন্য পরিষ্কার হবে।

