## ১. সম্পদ ক্রয় বনাম ব্যয়: ঐতিহাসিক গোল্ডেন রুল
> 🌟 **মূল নীতি:** পুনঃবিক্রয়ের উদ্দেশ্যে যা কেনা হয় তা **'পণ্য (Purchase)'**। কিন্তু ব্যবহারের উদ্দেশ্যে যা কেনা হয় তা **'স্থায়ী সম্পদ'**। সম্পদ কিনলে সংশ্লিষ্ট সম্পদের নামেই হিসাব খুলতে হবে!

### লেনদেন ১২: অফিসের ব্যবহারের জন্য একটি কম্পিউটার ও প্রিন্টার ক্রয় ৬০,০০০ টাকা
- **ভুল ধারণা:** ক্রয় হিসাব ডেবিট (ভুল!)
- **সঠিক যুক্তি:** এটি পণ্য নয়, অফিসের দীর্ঘমেয়াদী সরঞ্জাম।
- **জাবেদা:**
  - **অফিস সরঞ্জাম হিসাব ডেবিট ৬০,০০০** (সম্পদ বৃদ্ধি)
  - **নগদান হিসাব ক্রেডিট ৬০,০০০** (সম্পদ হ্রাস)

### লেনদেন ১৩: নতুন যন্ত্রপাতি ক্রয় ৫০,০০০ টাকা এবং তা কারখানায় বসানোর সংস্থাপন ব্যয় ৫,০০০ টাকা নগদে পরিশোধ
- **গোল্ডেন রুল:** কোনো স্থায়ী সম্পদ ব্যবহারের উপযোগী করার পূর্ব পর্যন্ত যাবতীয় খরচ (যেমন: পরিবহন, কুলির মজুরি, সংস্থাপন ব্যয়, শুল্ক) ঐ **সম্পদের মূল্যের সাথেই যোগ হয়**, আলাদা মজুরি বা সংস্থাপন হিসাব হবে না!
- **জাবেদা:**
  - **যন্ত্রপাতি হিসাব ডেবিট ৫৫,০০০** (৫০,০০০ + ৫,০০০) (সম্পদ বৃদ্ধি)
  - **নগদান হিসাব ক্রেডিট ৫৫,০০০** (সম্পদ হ্রাস)

### লেনদেন ১৪: পুরোনো আসবাবপত্র মেরামত খরচ ১,৫০০ টাকা
- **যুক্তি:** এটি নিয়মিত রক্ষণাবেক্ষণ ব্যয়, কোনো নতুন সম্পদ আসেনি। তাই মেরামত হিসাব হবে।
- **জাবেদা:**
  - **মেরামত হিসাব ডেবিট ১,৫০০** (ব্যয় বৃদ্ধি)
  - **নগদান হিসাব ক্রেডিট ১,৫০০** (সম্পদ হ্রাস)

### লেনদেন ১৫: ব্যবহৃত পুরোনো একটি টাইপরাইটার/আসবাবপত্র নগদে বিক্রয় ৪,০০০ টাকা
- **ভুল ধারণা:** বিক্রয় হিসাব ক্রেডিট (ভুল!)
- **সঠিক যুক্তি:** আসবাবপত্র চলে গেছে, তাই আসবাবপত্র হিসাবই ক্রেডিট হবে।
- **জাবেদা:**
  - **নগদান হিসাব ডেবিট ৪,০০০** (নগদ সম্পদ বৃদ্ধি)
  - **আসবাবপত্র হিসাব ক্রেডিট ৪,০০০** (স্থায়ী সম্পদ হ্রাস)

