## ২. ব্যাংকিং লেনদেনের সকল প্যাঁচের সহজ সমাধান

| ক্রম | লেনদেনের বিবরণ | জড়িত দুটি হিসাব ও প্রভাব | সঠিক জাবেদা দাখিলা |
| :---: | :--- | :--- | :--- |
| **১৬** | ব্যবসায়ের উদ্বৃত্ত নগদ ২৫,০০০ টাকা ব্যাংকে জমা দেওয়া হলো | ব্যাংক সম্পদ বাড়ে, নগদ সম্পদ কমে | **ব্যাংক হিসাব ডেবিট ২৫,০০০**<br>    **নগদান হিসাব ক্রেডিট ২৫,০০০** |
| **১৭** | ব্যবসায়ের প্রয়োজনীয় খরচের জন্য ব্যাংক হতে উত্তোলন ১০,০০০ টাকা | নগদ ক্যাশ বাড়ে, ব্যাংক জমা কমে | **নগদান হিসাব ডেবিট ১০,০০০**<br>    **ব্যাংক হিসাব ক্রেডিট ১০,০০০** |
| **১৮** | **মালিকের ব্যক্তিগত প্রয়োজনে** ব্যাংক হতে উত্তোলন ৬,০০০ টাকা | মালিকের উত্তোলন বাড়ে, ব্যাংক সম্পদ কমে | **উত্তোলন হিসাব ডেবিট ৬,০০০**<br>    **ব্যাংক হিসাব ক্রেডিট ৬,০০০** |
| **১৯** | গ্রাহক/দেনাদার সরাসরি ব্যবসায়ের ব্যাংক হিসাবে জমা দিল ১৫,০০০ টাকা | ব্যাংক সম্পদ বাড়ে, দেনাদার সম্পদ কমে | **ব্যাংক হিসাব ডেবিট ১৫,০০০**<br>    **প্রাপ্য হিসাব ক্রেডিট ১৫,০০০** |
| **২০** | ব্যাংক কর্তৃক চার্জ ধার্য করা হলো ৫০০ টাকা | প্রতিষ্ঠানের সেবা বাবদ খরচ বাড়ে, ব্যালেন্স কমে | **ব্যাংক চার্জ হিসাব ডেবিট ৫০০**<br>    **ব্যাংক হিসাব ক্রেডিট ৫০০** |
| **২১** | ব্যাংক সুদ মঞ্জুর করল ৮০০ টাকা | ব্যাংক আয় বৃদ্ধি, ব্যাংক জমা ব্যালেন্স বৃদ্ধি | **ব্যাংক হিসাব ডেবিট ৮০০**<br>    **ব্যাংক সুদ হিসাব ক্রেডিট ৮০০** |

> ⚠️ **পরীক্ষার ফাঁদ:**  
> - "অফিসের জন্য ব্যাংক হতে উত্তোলন" = **নগদান হিসাব ডে.** এবং **ব্যাংক হিসাব ক্র.**  
> - "মালিকের প্রয়োজনে ব্যাংক হতে উত্তোলন" = **উত্তোলন হিসাব ডে.** এবং **ব্যাংক হিসাব ক্র.**$lesson$,
