## ১. বকেয়া ও অগ্রিম খরচের জাবেদা

### লেনদেন ২২: কর্মচারীর বেতন বকেয়া রয়েছে ৭,০০০ টাকা
- **যুক্তি:** কর্মচারীর কাজ নেওয়া হয়েছে তাই চলতি বছরের বেতন খরচ হয়েছে, কিন্তু এখনো নগদ দেওয়া হয়নি বলে ভবিষ্যতে দেওয়ার দায় সৃষ্টি হয়েছে।
- **জাবেদা:**
  - **বেতন হিসাব ডেবিট ৭,০০০** (ব্যয় বৃদ্ধি)
  - **বকেয়া বেতন হিসাব ক্রেডিট ৭,০০০** (চলতি দায় বৃদ্ধি)

### লেনদেন ২৩: আগামী বছরের জন্য দোকান ভাড়া অগ্রিম প্রদান করা হলো ১২,০০০ টাকা
- **যুক্তি:** ভবিষ্যতের সুবিধার জন্য টাকা আগে দিলে তা বর্তমান সময়ে প্রতিষ্ঠানের জন্য সম্পদ।
- **জাবেদা:**
  - **অগ্রিম ভাড়া হিসাব ডেবিট ১২,০০০** (চলতি সম্পদ বৃদ্ধি)
  - **নগদান হিসাব ক্রেডিট ১২,০০০** (নগদ সম্পদ হ্রাস)

### লেনদেন ২৪: বিনিয়োগের সুদ অর্জিত হয়েছে কিন্তু পাওয়া যায়নি ৩,০০০ টাকা (বকেয়া আয়)
- **জাবেদা:**
  - **অনাদায়ী সুদ হিসাব ডেবিট ৩,০০০** (চলতি সম্পদ বৃদ্ধি)
  - **সুদ আয় হিসাব ক্রেডিট ৩,০০০** (আয় বৃদ্ধি)

### লেনদেন ২৫: গ্রাহকের নিকট হতে অগ্রিম পরামর্শ ফি গ্রহণ ৫,০০০ টাকা (অনুপার্জিত আয়)
- **যুক্তি:** সেবা দেওয়ার আগেই টাকা নিলে তা কাজ করে দেওয়ার দায় নির্দেশ করে।
- **জাবেদা:**
  - **নগদান হিসাব ডেবিট ৫,০০০** (সম্পদ বৃদ্ধি)
  - **অনুপার্জিত ফি হিসাব ক্রেডিট ৫,০০০** (চলতি দায় বৃদ্ধি)

---

## ২. বাট্টা ও পূর্ণ নিষ্পত্তির জাবেদা (Discount Masterclass)
বাট্টা দুই প্রকার:
১. **কারবারি বাট্টা (Trade Discount):** ক্রয়-বিক্রয়ের সময় পণ্যের তালিকা মূল্যের ওপর ছাড়। এটি **কখনো জাবেদায় লেখা হয় না**, শুধু মূল টাকা থেকে বাদ যায়।
২. **নগদ বাট্টা (Cash Discount):** দেনা-পাওনা দ্রুত পরিশোধের সময় নগদ ছাড়। এটি **অবশ্যই জাবেদায় লিখতে হয়**।

### লেনদেন ২৬: দেনাদার জাহিদের নিকট ১০,০০০ টাকার পূর্ণ নিষ্পত্তিতে ৯,৭০০ টাকা পাওয়া গেল
- **বিশ্লেষণ:** জাহিদের হিসাব ছিল ১০,০০০ টাকা। নগদ পাওয়া গেছে ৯,৭০০ টাকা। তাকে ছাড় দেওয়া হলো ৩০০ টাকা (প্রদত্ত বাট্টা)।
- **জাবেদা:**
  - **নগদান হিসাব ডেবিট ৯,৭০০** (নগদ সম্পদ বৃদ্ধি)
  - **প্রদত্ত বাট্টা হিসাব ডেবিট ৩০০** (ব্যয় বৃদ্ধি)
  - **প্রাপ্য হিসাব (জাহিদ) ক্রেডিট ১০,০০০** (দেনাদার সম্পদ সম্পূর্ণ নিঃশেষ)

### লেনদেন ২৭: পাওনাদার আকবরকে ৮,০০০ টাকার পূর্ণ নিষ্পত্তিতে ৭,৬০০ টাকা পরিশোধ করা হলো
- **জাবেদা:**
  - **প্রদেয় হিসাব (আকবর) ডেবিট ৮,০০০** (দায় সম্পূর্ণ বিলুপ্ত)
  - **নগদান হিসাব ক্রেডিট ৭,৬০০** (নগদ সম্পদ হ্রাস)
  - **প্রাপ্ত বাট্টা হিসাব ক্রেডিট ৪০০** (আয় বৃদ্ধি)

---

## ৩. অস্বাভাবিক ক্ষতি ও বীমা দাবি

### লেনদেন ২৮: আগুনে বিনষ্ট পণ্য ১০,০০০ টাকা (কোনো বীমা নেই)
- **জাবেদা:**
  - **আগুনে বিনষ্ট পণ্য ক্ষতি হিসাব ডেবিট ১০,০০০** (ক্ষতি/ব্যয় বৃদ্ধি)
  - **ক্রয় হিসাব ক্রেডিট ১০,০০০** (পণ্য বিনষ্ট হওয়ায় ক্রয় খরচ হ্রাস)

### লেনদেন ২৯: আগুনে বিনষ্ট পণ্য ১০,০০০ টাকা, কিন্তু বীমা কোম্পানি ৮,০০০ টাকার ক্ষতিপূরণ দাবি মেনে নিয়েছে
- **বিশ্লেষণ:** মোট ক্ষতি ১০,০০০ টাকার পণ্য। বীমা কোম্পানি দেবে ৮,০০০ টাকা (বীমা দাবি সম্পদ)। প্রকৃত নিট ক্ষতি হলো ২,০০০ টাকা।
- **জাবেদা:**
  - **বীমা দাবি হিসাব ডেবিট ৮,০০০** (প্রাপ্য সম্পদ বৃদ্ধি)
  - **বিবিধ ক্ষতি হিসাব ডেবিট ২,০০০** (প্রকৃত নিট ক্ষতি/ব্যয় বৃদ্ধি)
  - **ক্রয় হিসাব ক্রেডিট ১০,০০০** (মোট বিনষ্ট পণ্যের ক্রয় হ্রাস)

### লেনদেন ৩০: অনাদায়ী পাওনা বা কুঋণ ধার্য করা হলো ২,০০০ টাকা (যা আর কখনো আদায় হবে না)
- **জাবেদা:**
  - **অনাদায়ী পাওনা হিসাব ডেবিট ২,০০০** (ব্যয় বৃদ্ধি)
  - **প্রাপ্য হিসাব (দেনাদার) ক্রেডিট ২,০০০** (সম্পদ নিশ্চিত হ্রাস)$lesson$,
