## ১. জাবেদার মূল দুই বিভাগ:
১. **বিশেষ জাবেদা (Special Journals):** নির্দিষ্ট একই প্রকৃতির লেনদেন দ্রুত লেখার জন্য।
   - **ক্রয় জাবেদা:** শুধুমাত্র ধারে পণ্য ক্রয়।
   - **বিক্রয় জাবেদা:** শুধুমাত্র ধারে পণ্য বিক্রয়।
   - **ক্রয় ফেরত জাবেদা:** ধারে কেনা পণ্য ফেরত পাঠানোর জন্য (ডেবিট নোট সহ)।
   - **বিক্রয় ফেরত জাবেদা:** ধারে বেচা পণ্য ফেরত আসার জন্য (ক্রেডিট নোট সহ)।
   - **নগদ প্রাপ্তি জাবেদা (CRJ):** যাবতীয় নগদ বা চেক প্রাপ্তি।
   - **নগদ প্রদান জাবেদা (CPJ):** যাবতীয় নগদ বা চেক প্রদান।
২. **প্রকৃত জাবেদা (General/Proper Journal):** যে লেনদেনগুলো বিশেষ জাবেদায় যায় না (যেমন: প্রারম্ভিক দাখিলা, সমাপনী দাখিলা, সমন্বয় দাখিলা, ভুল সংশোধনী দাখিলা)।

---

## সৃজনশীল প্রশ্ন ০১ (প্রকৃত সাধারণ জাবেদা প্রস্তুতকরণ)
**উদ্দীপক:** জনাব রওশনের ২০২৩ সালের এপ্রিল মাসের কয়েকটি লেনদেন:
- এপ্রিল ১: নগদ ৬০,০০০ টাকা এবং ২০,০০০ টাকার পণ্যদ্রব্য নিয়ে ব্যবসা আরম্ভ করলেন।
- এপ্রিল ৫: চেকে পণ্য ক্রয় ২৫,০০০ টাকা।
- এপ্রিল ১০: বিজ্ঞাপন বাবদ ব্যয় ৫,০০০ টাকা।
- এপ্রিল ১৫: ১০% বাট্টায় জামালের নিকট ধারে পণ্য বিক্রয় ২০,০০০ টাকা।
- এপ্রিল ২০: ব্যক্তিগত প্রয়োজনে ব্যাংক থেকে উত্তোলন ৪,০০০ টাকা।
- এপ্রিল ২৫: জামালের নিকট হতে ১৮,০০০ টাকার পূর্ণ নিষ্পত্তিতে ১৭,৫০০ টাকা পাওয়া গেল।

**প্রশ্ন:**
- (ক) জনাব রওশনের প্রারম্ভিক মূলধনের পরিমাণ কত?
- (খ) এপ্রিল ১, ৫ ও ১০ তারিখের সাধারণ জাবেদা দাখিলা প্রস্তুত কর।
- (গ) এপ্রিল ১৫, ২০ ও ২৫ তারিখের লেনদেনগুলোর ডেবিট ও ক্রেডিট কারণসহ বিশ্লেষণ কর।

---

### সমাধান ০১:
#### (ক) প্রারম্ভিক মূলধনের পরিমাণ:
প্রারম্ভিক মূলধন = নগদ ৬০,০০০ + পণ্যদ্রব্য ২০,০০০ = **৮০,০০০ টাকা**।

#### (খ) জনাব রওশনের সাধারণ জাবেদা (এপ্রিল ১, ৫, ১০):

| তারিখ | হিসাবের শিরোনাম ও ব্যাখ্যা | খ.পৃ. | ডেবিট টাকা | ক্রেডিট টাকা |
| :---: | :--- | :---: | :---: | :---: |
| ২০২৩ এপ্রি ১ | নগদান হিসাব ডেবিট<br>ক্রয় হিসাব ডেবিট<br>    মূলধন হিসাব ক্রেডিট<br>*(যেহেতু নগদ অর্থ ও পণ্য নিয়ে ব্যবসায় শুরু করা হলো)* | | ৬০,০০০<br>২০,০০০<br>— | —<br>—<br>৮০,০০০ |
| এপ্রি ৫ | ক্রয় হিসাব ডেবিট<br>    ব্যাংক হিসাব ক্রেডিট<br>*(যেহেতু চেকে পণ্য ক্রয় করা হলো)* | | ২৫,০০০<br>— | —<br>২৫,০০০ |
| এপ্রি ১০ | বিজ্ঞাপন হিসাব ডেবিট<br>    নগদান হিসাব ক্রেডিট<br>*(যেহেতু বিজ্ঞাপনের খরচ নগদে প্রদান করা হলো)* | | ৫,০০০<br>— | —<br>৫,০০০ |

#### (গ) এপ্রিল ১৫, ২০ ও ২৫ তারিখের কারণসহ ডেবিট-ক্রেডিট বিশ্লেষণ:
- **এপ্রিল ১৫:**  
  কারবারি বাট্টা = `২০,০০০ × ১০% = ২,০০০ টাকা` (বাদ যাবে)। নিট ধারে বিক্রয় = ১৮,০০০ টাকা।  
  - **প্রাপ্য হিসাব (জামাল) ডেবিট ১৮,০০০ টাকা** (সম্পদ বৃদ্ধি পেয়েছে)।  
  - **বিক্রয় হিসাব ক্রেডিট ১৮,০০০ টাকা** (ব্যবসায়ের পণ্য বিক্রয় বাবদ আয় বৃদ্ধি পেয়েছে)।
- **এপ্রিল ২০:**  
  - **উত্তোলন হিসাব ডেবিট ৪,০০০ টাকা** (মালিকের ব্যক্তিগত উত্তোলনের ফলে মালিকানা স্বত্ব হ্রাস পেয়েছে)।  
  - **ব্যাংক হিসাব ক্রেডিট ৪,০০০ টাকা** (ব্যাংক থেকে টাকা কমে যাওয়ায় সম্পদ হ্রাস পেয়েছে)।
- **এপ্রিল ২৫:**  
  - **নগদান হিসাব ডেবিট ১৭,৫০০ টাকা** (নগদ সম্পদ বৃদ্ধি)।  
  - **প্রদত্ত বাট্টা হিসাব ডেবিট ৫০০ টাকা** (ব্যয় বৃদ্ধি)।  
  - **প্রাপ্য হিসাব (জামাল) ক্রেডিট ১৮,০০০ টাকা** (সম্পদ সম্পূর্ণরূপে হ্রাস)।

---

## সৃজনশীল প্রশ্ন ০২ (ক্রয় জাবেদা প্রস্তুতকরণ)
**উদ্দীপক:** মেসার্স তুষার ট্রেডার্স এর ২০২৩ সালের মার্চ মাসের ক্রয় সংক্রান্ত তথ্য:
- মার্চ ৫: সুরমা ব্রাদার্সের নিকট হতে প্রতি কেজি ১০০ টাকা দরে ২০০ কেজি চাল ক্রয়। কারবারি বাট্টা ৫%, চালান নং ১০১, শর্ত ২/১০, নিট ৩০।
- মার্চ ১২: রূপসা স্টোরস হতে নগদে পণ্য ক্রয় ২০,০০০ টাকা।
- মার্চ ২০: কর্ণফুলী ট্রেডার্সের নিকট হতে প্রতিটি ৫০০ টাকা দরে ৬০টি শার্ট ক্রয়। কারবারি বাট্টা ১০%, পরিবহন খরচ ১,০০০ টাকা, চালান নং ২০৫।

**প্রশ্ন:**
- (ক) যে লেনদেনটি ক্রয় জাবেদায় অন্তর্ভুক্ত হবে না তার কারণ ব্যাখ্যা কর।
- (খ) উপযুক্ত তথ্যের আলোকে মেসার্স তুষার ট্রেডার্স এর 'ক্রয় জাবেদা' প্রস্তুত কর।

---

### সমাধান ০২:
#### (ক) মার্চ ১২ তারিখের লেনদেনটি ক্রয় জাবেদায় যাবে না:
**কারণ:** মার্চ ১২ তারিখের ক্রয়টি নগদে সম্পন্ন হয়েছে। ক্রয় জাবেদায় **শুধুমাত্র ধারে (বাকিতে) পণ্য ক্রয়** লিপিবদ্ধ করা হয়। নগদ ক্রয় লিপিবদ্ধ করা হয় 'নগদ প্রদান জাবেদায় (Cash Payment Journal)'।

#### (খ) মেসার্স তুষার ট্রেডার্স-এর ক্রয় জাবেদা:
*চালানের হিসাব গণনা:*
1. **সুরমা ব্রাদার্স:** মোট মূল্য = `২০০ × ১০০ = ২০,০০০ টাকা`। ৫% বাট্টা = ১,০০০ টাকা। নিট মূল্য = `১৯,০০০ টাকা`।
2. **কর্ণফুলী ট্রেডার্স:** মোট শার্ট = `৬০ × ৫০০ = ৩০,০০০ টাকা`। ১০% বাট্টা = ৩,০০০ টাকা। নিট = ২৭,০০০ টাকা + পরিবহন খরচ ১,০০০ = `২৮,০০০ টাকা`।

**ক্রয় জাবেদা ছক:**

| তারিখ | ক্রেডিট হিসাব খাত | শর্ত | চালান নং | সূত্র | ক্রয় হিসাব (ডে.) / প্রদেয় হিসাব (ক্র.) |
| :---: | :--- | :---: | :---: | :---: | :---: |
| ২০২৩ মার্চ ৫ | সুরমা ব্রাদার্স | ২/১০, নিট ৩০ | ১০১ | ✓ | ১৯,০০০ |
| মার্চ ২০ | কর্ণফুলী ট্রেডার্স | | ২০৫ | ✓ | ২৮,০০০ |
| | **মোট যোগফল** | | | | **৪৭,০০০** |$lesson$,
        5
    );

