        $lesson$# পাঠ ৬: সৃজনশীল প্রশ্ন ০৩, ০৪, ০৫ এবং জাবেদার ১০টি গোল্ডেন সিক্রেট

## সৃজনশীল প্রশ্ন ০৩ (নগদ প্রাপ্তি ও প্রদান জাবেদার মৌলিক শর্ত)
**প্রশ্ন:** নগদ প্রাপ্তি জাবেদা (CRJ) এবং নগদ প্রদান জাবেদায় (CPJ) কোন কোন লেনদেন যায় না?
**উত্তর:**
১. অনগদ লেনদেন (যেমন: ধারে ক্রয়, ধারে বিক্রয়, অবচয়, অনাদায়ী পাওনা)।
২. ক্রয় ফেরত ও বিক্রয় ফেরত।
৩. মালিক কর্তৃক ব্যক্তিগত ব্যবহারের জন্য পণ্য উত্তোলন।
৪. বিজ্ঞাপনের উদ্দেশ্যে বিনামূল্যে পণ্য বিতরণ।
*(কারণ এগুলোর কোনোটিতেই প্রকৃত নগদ টাকা আসেও না, যায়ও না)*।

---

## সৃজনশীল প্রশ্ন ০৪ (ভুল সংশোধনী জাবেদার সহজ কৌশল)
**লেনদেন:** কর্মচারীকে বেতন প্রদান ৫,০০০ টাকা ভুলবশত 'ভাড়া হিসাবে' ডেবিট করা হয়েছে।
- **ভুল দাখিলা হয়েছিল:** ভাড়া হিসাব ডেবিট ৫,০০০ / নগদান হিসাব ক্রেডিট ৫,০০০।
- **হওয়া উচিত ছিল:** বেতন হিসাব ডেবিট ৫,০০০ / নগদান হিসাব ক্রেডিট ৫,০০০।
- **সংশোধন কৌশল:** বেতন যেহেতু ডেবিট হয়নি, তাই বেতনকে ডেবিট করো। আর ভাড়া যেহেতু অন্যায়ভাবে ডেবিট করা হয়েছিল, তাকে বাতিল করতে ক্রেডিট করো!
- **সংশোধনী জাবেদা:**
  - **বেতন হিসাব ডেবিট ৫,০০০**
  - **ভাড়া হিসাব ক্রেডিট ৫,০০০**

---

## সৃজনশীল প্রশ্ন ০৫ (উত্তোলনের যাবতীয় রূপরেখা)
মালিকের সাথে সম্পর্কিত উত্তোলনের সঠিক জাবেদাসমূহ এক নজরে:
1. **কারবার থেকে নগদ উত্তোলন:** উত্তোলন হিসাব ডেবিট / নগদান হিসাব ক্রেডিট।
2. **কারবার থেকে পণ্য উত্তোলন:** উত্তোলন হিসাব ডেবিট / ক্রয় হিসাব ক্রেডিট।
3. **কারবারের ব্যাংক থেকে ব্যক্তিগত উত্তোলন:** উত্তোলন হিসাব ডেবিট / ব্যাংক হিসাব ক্রেডিট।
4. **মালিকের আয়কর কারবার হতে প্রদান:** আয়কর হলো মালিকের ব্যক্তিগত ব্যয়। তাই: উত্তোলন হিসাব ডেবিট / নগদান হিসাব ক্রেডিট।
5. **মালিকের জীবন বীমা প্রিমিয়াম কারবার হতে প্রদান:** এটিও ব্যক্তিগত ব্যয়। তাই: উত্তোলন হিসাব ডেবিট / নগদান হিসাব ক্রেডিট।
6. **মালিকের ছেলের স্কুলের বেতন কারবার থেকে প্রদান:** এটিও ব্যক্তিগত ব্যয়। তাই: উত্তোলন হিসাব ডেবিট / নগদান হিসাব ক্রেডিট।

---

## 🎯 পরীক্ষায় এ প্লাস পাওয়ার জন্য জাবেদার ১০টি গোল্ডেন সিক্রেট (Golden Secrets)
১. **পণ্য নামে কোনো হিসাব হয় না:** কেনার সময় 'ক্রয় হিসাব' এবং বিক্রয়ের সময় 'বিক্রয় হিসাব' হবে।
২. **ব্যক্তির নাম থাকলে:** নগদ বা চেকের উল্লেখ না থাকলে কেবল ব্যক্তির নাম থাকা মানেই তা **শতভাগ ধারে লেনদেন**।
৩. **চেক পেলে সাধারণত ব্যাংক হিসাব ডেবিট হয়:** কারণ চেক ব্যাংকে জমা দিয়ে ভাঙাতে হয়।
৪. **সম্পদ ক্রয়ের খরচ:** সংস্থাপন ব্যয়, পরিবহন খরচ, শুল্ক ইত্যাদি ঐ স্থায়ী সম্পদের মূল্যের সাথেই যোগ হয়।
৫. **কারবারি বাট্টা কখনো জাবেদায় বসে না:** এটি কেবল চালানে বাদ যায়। কিন্তু নগদ বাট্টা অবশ্যই জাবেদায় ডেবিট বা ক্রেডিট হয়।
৬. **পণ্য উত্তোলন বা বিনামূল্যে পণ্য বিতরণ:** এই দুই ক্ষেত্রে পণ্য চলে যায় বলে **ক্রয় হিসাব ক্রেডিট** করতে হয়।
৭. **বকেয়া খরচ হলো দায় (Credit):** আর অগ্রিম খরচ হলো সম্পদ (Debit)।
৮. **বকেয়া আয় হলো সম্পদ (Debit):** আর অগ্রিম আয় হলো দায় (Credit)।
৯. **ব্যাংক চার্জ ব্যবসায়ের ব্যয়:** তাই ব্যাংক চার্জ হিসাব ডেবিট এবং ব্যাংক ব্যালেন্স কমে বলে ব্যাংক হিসাব ক্রেডিট।
১০. **ব্যাংক সুদ ব্যবসায়ের আয়:** তাই ব্যাংক সুদ হিসাব ক্রেডিট এবং ব্যাংক জমার পরিমাণ বৃদ্ধি পায় বলে ব্যাংক হিসাব ডেবিট।$lesson$,
        6
    );

