-- ==================== seed_chapter_7_ledger.sql ====================
-- ==============================================================================
-- CHAPTER 7: খতিয়ান (Ledger) - COMPREHENSIVE SEED SCRIPT
-- ==============================================================================
-- Standardized with rich Markdown tables, T-Account & Running Balance formats,
-- posting rules, balancing (c/d & b/d), General vs Subsidiary ledgers,
-- 5 Board-standard Creative Questions (CQs), and 30 high-yield Exam Questions (6 rounds).
-- ==============================================================================

DO $$
DECLARE
    ch_id UUID;
BEGIN
    SELECT id INTO ch_id FROM chapters WHERE order_index = 7 LIMIT 1;
    
    IF ch_id IS NULL THEN
        RAISE NOTICE 'Chapter 7 (order_index = 7) not found. Skipping.';
        RETURN;
    END IF;

    -- Update chapter title
    UPDATE chapters 
    SET title_bn = '৭ম অধ্যায়: খতিয়ান (Ledger)',
        title_en = 'Chapter 7: Ledger'
    WHERE id = ch_id;

    -- Clean old lessons and questions
    DELETE FROM lessons WHERE chapter_id = ch_id;
    DELETE FROM exam_questions WHERE chapter_id = ch_id;

    -- ==========================================================================
    -- LESSON 1: খতিয়ানের ধারণা, বৈশিষ্ট্য ও গুরুত্ব
    -- ==========================================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        ch_id,
        $lesson$# পাঠ ১: খতিয়ানের ধারণা, বৈশিষ্ট্য ও গুরুত্ব

## ১. খতিয়ান কী? (Concept of Ledger)
ব্যবসায়ের লেনদেনসমূহ প্রথমে প্রাথমিক বই জাবেদায় লেখার পর নির্দিষ্ট নিয়ম অনুযায়ী শ্রেণিবদ্ধ করে পৃথক পৃথক শিরোনামে স্থায়ীভাবে যে বইতে লিপিবদ্ধ করা হয়, তাকে **খতিয়ান (Ledger)** বলে।

> **সংজ্ঞা:** "খতিয়ান হলো হিসাববিজ্ঞানের **পাকা বই (Final/Principal Book)** বা **সকল বইয়ের রাজা (King of all books)**।"

---

## ২. খতিয়ানকে 'পাকা বই' বা 'সকল বইয়ের রাজা' বলা হয় কেন?
১. **স্থায়ী রেকর্ড:** জাবেদা ঐচ্ছিক বা সহকারী বই, কিন্তু খতিয়ান সংরক্ষণ করা বাধ্যতামূলক।
২. **হিসাবের জের নির্ণয়:** নির্দিষ্ট সময় শেষে প্রতিটি হিসাবের নিট উদ্বৃত্ত বা জের (Balance) শুধুমাত্র খতিয়ান থেকেই জানা যায়।
৩. **আর্থিক বিবরণী প্রস্তুত:** খতিয়ানের জের দিয়েই পরবর্তীতে রেওয়ামিল এবং বিশদ আয় বিবরণী ও আর্থিক অবস্থার বিবরণী প্রস্তুত করা হয়।

---

## ৩. খতিয়ানের প্রধান বৈশিষ্ট্যসমূহ
- প্রতিটি হিসাবের জন্য পৃথক শিরোনাম (Title) ও হিসাব কোড নম্বর থাকে।
- লেনদেনসমূহ তারিখের ক্রমানুসারে ডেবিট ও ক্রেডিট বিশ্লেষণ করে পোস্টিং দেওয়া হয়।
- নির্দিষ্ট সময় পর পর প্রতিটি হিসাবের উদ্বৃত্ত বা জের (Balance) নির্ণয় করা হয়।
- খতিয়ানে 'জাবেদা পৃষ্ঠা' (J.F.) উল্লেখ থাকে, যা তথ্যের সত্যতা যাচাই সহজ করে।

---

## ৪. জাবেদা ও খতিয়ানের তুলনামূলক পার্থক্য

| পার্থক্যের বিষয় | জাবেদা (Journal) | খতিয়ান (Ledger) |
| :--- | :--- | :--- |
| **বইয়ের প্রকৃতি** | প্রাথমিক বা সহকারী বই (Book of Prime Entry) | পাকা বা চূড়ান্ত বই (Principal/Final Book) |
| **লিপিবদ্ধকরণ** | কালানুক্রমিক ও সংক্ষিপ্ত ব্যাখ্যাসহ | শ্রেণিবদ্ধভাবে পৃথক শিরোনামে |
| **উদ্দেশ্য** | লেনদেনের প্রাথমিক হিসাব রাখা | নির্দিষ্ট হিসাবের নিট স্থিতি/জের জানা |
| **বাধ্যবাধকতা** | তৈরি করা ঐচ্ছিক (Optional) | প্রস্তুত করা বাধ্যতামূলক (Mandatory) |
| **পৃষ্ঠা নম্বর** | খতিয়ান পৃষ্ঠা (L.F.) লেখা হয় | জাবেদা পৃষ্ঠা (J.F.) লেখা হয় |
| **শুদ্ধতা যাচাই** | রেওয়ামিল তৈরি করা যায় না | খতিয়ানের জের দিয়ে রেওয়ামিল তৈরি হয় |

---

## ৫. বাস্তব প্রয়োগ ও উদাহরণ
মনে করো, মার্চ মাসে নগদে ১০ বার লেনদেন হয়েছে। জাবেদা দেখে মাসের শেষ দিন এক নজরে ক্যাশে কত টাকা জমা আছে তা বলা অসম্ভব। কিন্তু খতিয়ানের **'নগদান হিসাব'** দেখলে ১ সেকেন্ডেই বলে দেওয়া যায় মোট কত টাকা নগদ জমা আছে!$lesson$,
        1
    );

    -- ==========================================================================
    -- LESSON 2: খতিয়ানের ছক: টি-ছক বনাম চলমান জের ছক
    -- ==========================================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        ch_id,
        $lesson$# পাঠ ২: খতিয়ানের ছকসমূহ (টি-ছক বনাম চলমান জের ছক)

খতিয়ান প্রধানত দুটি পদ্ধতিতে প্রস্তুত করা হয়:
১. **সনাতন পদ্ধতি:** 'টি-ছক' (T-Account / Traditional Format)
২. **আধুনিক পদ্ধতি:** 'চলমান জের ছক' (Running Balance Format)

---

## ১. 'টি-ছক' (T-Account) এর পূর্ণাঙ্গ রূপরেখা
ইংরেজি 'T' অক্ষরের মতো দেখতে হওয়ায় একে টি-ছক বলে। এই ছকে হিসাবের পৃষ্ঠাকে সমান দুই ভাগে ভাগ করা হয়—বাম দিক **ডেবিট** এবং ডান দিক **ক্রেডিট**।
- **মোট কলাম সংখ্যা:** **৮টি** (ডেবিট পাশে ৪টি, ক্রেডিট পাশে ৪টি)।

### টি-ছকের নমুনা ছক:
**হিসাবের নাম: নগদান হিসাব** | **হিসাব কোড নং: ১০১**
```
ডেবিট (Dr.)                                                     ক্রেডিট (Cr.)
-----------------------------------------------------------------------------
তারিখ  | বিবরণ        | জা.পৃ. | টাকা   | তারিখ  | বিবরণ        | জা.পৃ. | টাকা
-----------------------------------------------------------------------------
২০২৩   |              |        |        | ২০২৩   |              |        |
মে ০১  | মূলধন হিসাব  | ১      | ৫০,০০০ | মে ০৫  | ক্রয় হিসাব   | ২      | ২০,০০০
মে ১০  | বিক্রয় হিসাব | ৩      | ৩০,০০০ | মে ৩১  | ব্যালেন্স c/d|        | ৬০,০০০
-----------------------------------------------------------------------------
       | মোট          |        | ৮০,০০০ |        | মোট          |        | ৮০,০০০
-----------------------------------------------------------------------------
জুন ০১ | ব্যালেন্স b/d|        | ৬০,০০০ |        |              |        |
```

---

## ২. 'চলমান জের ছক' (Running Balance Format)
আধুনিক ও আন্তর্জাতিকভাবে সবচেয়ে জনপ্রিয় পদ্ধতি। এই ছকে প্রতিটি লেনদেন লিপিবদ্ধ করার সাথে সাথেই হিসাবের সর্বশেষ ব্যালেন্স বা জের বের হয়ে যায়।
- **মোট কলাম সংখ্যা:** **৭টি** (তারিখ, বিবরণ, জা.পৃ., ডেবিট টাকা, ক্রেডিট টাকা, উদ্বৃত্ত/জের [ডেবিট, ক্রেডিট])।

### চলমান জের ছকের নমুনা ছক:
**হিসাবের নাম: নগদান হিসাব** | **হিসাব কোড নং: ১০১**

| তারিখ | বিবরণ | জা.পৃ. | ডেবিট টাকা | ক্রেডিট টাকা | জের (ডেবিট) | জের (ক্রেডিট) |
| :--- | :--- | :--- | :--- | :--- | :--- | :--- |
| ২০২৩ মে ১ | মূলধন হিসাব | ১ | ৫০,০০০ | | ৫০,০০০ | |
| মে ৫ | ক্রয় হিসাব | ২ | | ২০,০০০ | ৩০,০০০ | |
| মে ১০ | বিক্রয় হিসাব | ৩ | ৩০,০০০ | | ৬০,০০০ | |

---

## ৩. টি-ছক ও চলমান জের ছকের তুলনামূলক বিশ্লেষণ

| তুলনার বিষয় | টি-ছক (সনাতন পদ্ধতি) | চলমান জের ছক (আধুনিক পদ্ধতি) |
| :--- | :--- | :--- |
| **কলাম সংখ্যা** | ৮টি কলাম | ৭টি কলাম |
| **অংশের বিন্যাস** | ডেবিট ও ক্রেডিট দুটি পৃথক অংশে বিভক্ত | একক ছকে সমন্বিত |
| **জের নির্ণয়** | নির্দিষ্ট সময় শেষে (মাসান্তে) টানা হয় | প্রতিটি লেনদেন লেখার সাথে সাথে |
| **c/d ও b/d ব্যবহার**| ব্যালেন্সিংয়ে c/d ও b/d লেখা আবশ্যক | c/d ও b/d লেখার কোনো প্রয়োজন নেই |
| **জনপ্রিয়তা ও সময়** | সময়সাপেক্ষ ও সনাতন | আধুনিক, দ্রুত ও স্বয়ংক্রিয় বান্ধব |$lesson$,
        2
    );

