## ১. পোস্টিং (Posting) কী ও কীভাবে করতে হয়?
জাবেদা দাখিলা থেকে হিসাবের খতিয়ানে স্থানান্তর করার প্রক্রিয়াকে **পোস্টিং (Posting)** বা স্থানান্তরকরণ বলে।

### পোস্টিংয়ের ৪টি গোল্ডেন রুল:
১. **হিসাবের শিরোনাম:** যে হিসাবটি খতিয়ানভুক্ত করা হচ্ছে, পৃষ্ঠার উপরে সেই হিসাবের নাম হবে (যেমন: 'নগদান হিসাব')।
২. **বিপরীত দাখিলার নাম:** বিবরণের ঘরে সংশ্লিষ্ট জাবেদার **বিপরীত হিসাবের নাম** লিখতে হবে।
৩. **টাকার কলাম:** জাবেদায় হিসাবটি যে পাশে (ডেবিট বা ক্রেডিট) ছিল, টাকা খতিয়ানের সেই পাশেই বসবে।
৪. **পৃষ্ঠা নম্বর:** খতিয়ানে জাবেদা পৃষ্ঠা (J.F.) এবং জাবেদায় খতিয়ান পৃষ্ঠা (L.F.) উল্লেখ করতে হবে।

---

## ২. ব্যালেন্সিং বা জের নির্ণয় (Balancing)
হিসাবের ডেবিট ও ক্রেডিট পাশের যোগফলের পার্থক্য বা ব্যবধান নির্ণয় করার নামই **জের টানা বা ব্যালেন্সিং (Balancing)**।

### গুরুত্বপূর্ণ সংকেতের পূর্ণরূপ ও অর্থ:
- **c/d (Carried Down):** নিচে নীত বা স্থানান্তর করা হলো (চলতি মাসের শেষ তারিখে ঘাটতি দিকে বসে)।
- **b/d (Brought Down):** উপর থেকে আনীত (পরবর্তী মাসের ১ তারিখে বিপরীত দিকে বসে)।
- **c/f (Carried Forward):** সম্মুখে নীত (পৃষ্ঠার শেষে স্থানান্তরের সময়)।
- **b/f (Brought Forward):** পেছন থেকে আনীত (নতুন পৃষ্ঠার শুরুতে)।

---

## ৩. ডেবিট জের ও ক্রেডিট জের এর অর্থ

```
+-------------------------------------------------------------+
| ডেবিট যোগফল > ক্রেডিট যোগফল  ==> ডেবিট জের (Debit Balance)  |
| ক্রেডিট যোগফল > ডেবিট যোগফল  ==> ক্রেডিট জের (Credit Balance)|
| ডেবিট যোগফল = ক্রেডিট যোগফল  ==> শুন্য উদ্বৃত্ত (Nil Balance)  |
+-------------------------------------------------------------+
```

### কোন হিসাব কোন জের নির্দেশ করে?
1. **ডেবিট জের নির্দেশ করে:** সকল প্রকার সম্পদ (নগদ, ব্যাংক, আসবাবপত্র, দেনাদার) এবং সকল প্রকার ব্যয় (বেতন, ভাড়া, ক্রয়, মজুরি)।
2. **ক্রেডিট জের নির্দেশ করে:** সকল প্রকার দায় (পাওনাদার, ব্যাংক ঋণ), মালিকানা স্বত্ব (মূলধন) এবং সকল প্রকার আয় (বিক্রয়, প্রাপ্ত সুদ, প্রাপ্ত কমিশন)।

> **টিপস:** উত্তোলন (Drawings) মালিকানা স্বত্ব হ্রাস করে বলে এর সাধারণ জের ডেবিট হয়।$lesson$,
        3
    );

