    -- LESSON 4: সাধারণ খতিয়ান বনাম সহকারী খতিয়ান
    -- ==========================================================================
    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (
        ch_id,
        $lesson$# পাঠ ৪: সাধারণ খতিয়ান বনাম সহকারী খতিয়ান

ব্যবসায়ের আকার বড় হলে শুধুমাত্র একটি খতিয়ানে শত শত দেনাদার ও পাওনাদারের হিসাব রাখা অসম্ভব। তাই খতিয়ানকে দুই ভাগে ভাগ করা হয়:
১. **সাধারণ খতিয়ান (General Ledger)**
২. **সহকারী খতিয়ান (Subsidiary Ledger)**

---

## ১. সাধারণ খতিয়ান (General Ledger)
ব্যবসায়ের যাবতীয় প্রধান হিসাব খাতসমূহ (যেমন: নগদান হিসাব, ক্রয় হিসাব, বিক্রয় হিসাব, বেতন হিসাব, দেনাদার নিয়ন্ত্রণ হিসাব, পাওনাদার নিয়ন্ত্রণ হিসাব) যে বইতে রাখা হয়, তাকে সাধারণ খতিয়ান বলে।
- **নিয়ন্ত্রণ হিসাব (Control Account):** দেনাদারদের মোট টাকার জন্য 'প্রাপ্য হিসাব' বা 'দেনাদার হিসাব' এবং পাওনাদারদের মোট টাকার জন্য 'প্রদেয় হিসাব' সাধারণ খতিয়ানে খোলা হয়।

---

## ২. সহকারী খতিয়ান (Subsidiary Ledger)
প্রতিটি দেনাদার ও পাওনাদারের নামে পৃথক পৃথক যে খতিয়ান খোলা হয়, তাকে **সহকারী খতিয়ান** বলে।
- উদাহরণ: মি. রহিম হিসাব, মেসার্স করিম ব্রাদার্স হিসাব, যমুনা ট্রেডার্স হিসাব।
- **উদ্দেশ্য:** নির্দিষ্ট গ্রাহক বা সরবরাহকারীর কাছে কত পাওনা বা দেনা রয়েছে তা তাৎক্ষণিকভাবে জানা।

---

## ৩. সাধারণ খতিয়ান ও সহকারী খতিয়ানের সম্পর্ক

```
+-----------------------------------------------------------------+
| সকল দেনাদারের সহকারী খতিয়ানের সমষ্টি = সাধারণ খতিয়ানের দেনাদার জের |
| সকল পাওনাদারের সহকারী খতিয়ানের সমষ্টি = সাধারণ খতিয়ানের পাওনাদার জের|
+-----------------------------------------------------------------+
```

### বাস্তব উদাহরণ:
ধরা যাক, প্রতিষ্ঠানের তিনজন দেনাদার আছেন:
- রফিক ট্রেডার্স: ১০,০০০ টাকা
- শফিক ব্রাদার্স: ১৫,০০০ টাকা
- বরকত স্টোর: ২৫,০০০ টাকা

এখানে রফিক, শফিক ও বরকতের পৃথক হিসাব হলো **সহকারী খতিয়ান**।
আর সাধারণ খতিয়ানে 'দেনাদার হিসাব'-এর ব্যালেন্স প্রদর্শিত হবে: `১০,০০০ + ১৫,০০০ + ২৫,০০০ = ৫০,০০০ টাকা`।

---

## ৪. তুলনামূলক টেবিল

| বৈশিষ্ট্য | সাধারণ খতিয়ান | সহকারী খতিয়ান |
| :--- | :--- | :--- |
| **হিসাবের ধরন** | সামগ্রিক ও নিয়ন্ত্রণমূলক প্রধান হিসাবসমূহ | প্রতিটি ব্যক্তি বা প্রতিষ্ঠানের পৃথক হিসাব |
| **ব্যবহার** | সরাসরি রেওয়ামিল তৈরিতে ব্যবহৃত হয় | রেওয়ামিল তৈরিতে সরাসরি ব্যবহৃত হয় না |
| **তথ্য বিবরণ** | মোট দেনা বা পাওনার সামগ্রিক চিত্র | সুনির্দিষ্ট ব্যক্তির নিকট দেনা-পাওনা |$lesson$,
        4
    );

