        ch_id,
        $lesson$# পাঠ ৫: বোর্ড স্ট্যান্ডার্ড সৃজনশীল প্রশ্ন ০১ ও ০২ (পূর্ণাঙ্গ সমাধান)

## সৃজনশীল প্রশ্ন ০১ (টি-ছকে খতিয়ান প্রস্তুতকরণ)
**উদ্দীপক:** জনাব সালমান ২০২৩ সালের জুন মাসে নগদ ৫০,০০০ টাকা নিয়ে ব্যবসা শুরু করেন। জুন মাসে তাঁর লেনদেনগুলো ছিল:
- জুন ৫: ধারে পণ্য ক্রয় ২০,০০০ টাকা।
- জুন ১২: নগদে পণ্য বিক্রয় ৩৫,০০০ টাকা।
- জুন ১৮: পাওনাদারকে পরিশোধ ১০,০০০ টাকা।
- জুন ২৫: বেতন প্রদান ৫,০০০ টাকা।

**প্রশ্ন:**
- (ক) জনাব সালমানের নিট নগদ অন্তর্গমন (Cash Inflow) কত?
- (খ) 'টি-ছক' পদ্ধতিতে 'নগদান হিসাব' প্রস্তুত কর।
- (গ) চলমান জের ছকে 'পাওনাদার হিসাব' প্রস্তুত কর।

---

### সমাধান ০১:
#### (ক) নিট নগদ অন্তর্গমন নির্ণয়:
নগদ অন্তর্গমন = মূলধন বাবদ আনয়ন ৫০,০০০ + নগদ বিক্রয় ৩৫,০০০ = **৮৫,০০০ টাকা**।

---

#### (খ) টি-ছকে 'নগদান হিসাব':
**হিসাবের নাম: নগদান হিসাব** | **হিসাব কোড: ১০১**

```
ডেবিট (Dr.)                                                     ক্রেডিট (Cr.)
-----------------------------------------------------------------------------
তারিখ  | বিবরণ        | জা.পৃ. | টাকা   | তারিখ  | বিবরণ        | জা.পৃ. | টাকা
-----------------------------------------------------------------------------
২০২৩   |              |        |        | ২০২৩   |              |        |
জুন ০১ | মূলধন হিসাব  |        | ৫০,০০০ | জুন ১৮ | পাওনাদার হি. |        | ১০,০০০
জুন ১২ | বিক্রয় হিসাব |        | ৩৫,০০০ | জুন ২৫ | বেতন হিসাব   |        |  ৫,০০০
       |              |        |        | জুন ৩০ | ব্যালেন্স c/d|        | ৭০,০০০
-----------------------------------------------------------------------------
       | মোট          |        | ৮৫,০০০ |        | মোট          |        | ৮৫,০০০
-----------------------------------------------------------------------------
জুলাই ১| ব্যালেন্স b/d|        | ৭০,০০০ |        |              |        |
```

---

#### (গ) চলমান জের ছকে 'পাওনাদার হিসাব':
**হিসাবের নাম: পাওনাদার হিসাব**

| তারিখ | বিবরণ | জা.পৃ. | ডেবিট টাকা | ক্রেডিট টাকা | জের (ডেবিট) | জের (ক্রেডিট) |
| :--- | :--- | :--- | :--- | :--- | :--- | :--- |
| ২০২৩ জুন ৫ | ক্রয় হিসাব | | | ২০,০০০ | | ২০,০০০ |
| জুন ১৮ | নগদান হিসাব | | ১০,০০০ | | | ১০,০০০ |

**মন্তব্য:** পাওনাদার হিসাবের ক্রেডিট জের **১০,০০০ টাকা**।

---

## সৃজনশীল প্রশ্ন ০২ (সহকারী খতিয়ান প্রস্তুত)
**উদ্দীপক:** মেসার্স আলফা ট্রেডার্স ২০২৩ সালের এপ্রিল মাসে ধারে পণ্য বিক্রয় করেন:
- এপ্রিল ২: রহমান ব্রাদার্স এর নিকট বিক্রয় ১২,০০০ টাকা।
- এপ্রিল ৮: শফিক স্টোরস এর নিকট বিক্রয় ১৮,০০০ টাকা।
- এপ্রিল ১৫: রহমান ব্রাদার্স হতে নগদ প্রাপ্তি ৮,০০০ টাকা।
- এপ্রিল ২২: শফিক স্টোরস পণ্য ফেরত দিল ২,০০০ টাকা।

**প্রশ্ন:**
- (ক) এপ্রিল মাসে মোট ধারে বিক্রয়ের পরিমাণ কত?
- (খ) সহকারী খতিয়ানে 'রহমান ব্রাদার্স হিসাব' এবং 'শফিক স্টোরস হিসাব' প্রস্তুত কর (চলমান জের ছকে)।
- (গ) সাধারণ খতিয়ানে 'প্রাপ্য হিসাব' (দেনাদার নিয়ন্ত্রণ হিসাব) প্রস্তুত কর।

---

### সমাধান ০২:
#### (ক) মোট ধারে বিক্রয় = ১২,০০০ + ১৮,০০০ = ৩০,০০০ টাকা।

#### (খ) সহকারী খতিয়ান (চলমান জের ছক):
**হিসাবের নাম: রহমান ব্রাদার্স হিসাব**

| তারিখ | বিবরণ | ডেবিট টাকা | ক্রেডিট টাকা | জের (ডেবিট) | জের (ক্রেডিট) |
| :--- | :--- | :--- | :--- | :--- | :--- |
| এপ্রিল ০২ | বিক্রয় হিসাব | ১২,০০০ | | ১২,০০০ | |
| এপ্রিল ১৫ | নগদান হিসাব | | ৮,০০০ | ৪,০০০ | |

**হিসাবের নাম: শফিক স্টোরস হিসাব**

| তারিখ | বিবরণ | ডেবিট টাকা | ক্রেডিট টাকা | জের (ডেবিট) | জের (ক্রেডিট) |
| :--- | :--- | :--- | :--- | :--- | :--- |
| এপ্রিল ০৮ | বিক্রয় হিসাব | ১৮,০০০ | | ১৮,০০০ | |
| এপ্রিল ২২ | বিক্রয় ফেরত হিসাব | | ২,০০০ | ১৬,০০০ | |

#### (গ) সাধারণ খতিয়ান: 'প্রাপ্য হিসাব'
- মোট বিক্রয় বাবদ ডেবিট: ৩০,০০০ টাকা
- নগদ প্রাপ্তি বাবদ ক্রেডিট: ৮,০০০ টাকা
- বিক্রয় ফেরত বাবদ ক্রেডিট: ২,০০০ টাকা
- **প্রাপ্য হিসাবের নিট ডেবিট জের:** `৩০,০০০ - (৮,০০০ + ২,০০০) = ২০,০০০ টাকা`।
*(যাচাই: রহমান ৪,০০০ + শফিক ১৬,০০০ = ২০,০০০ টাকা! নিখুঁত মিল)*$lesson$,
        5
    );

