## সৃজনশীল প্রশ্ন ০৩ (ব্যাংক হিসাব ও উত্তোলন হিসাবের ব্যালেন্সিং)
**উদ্দীপক:** জনাব শওকত মে মাসে ব্যাংকে ৫০,০০০ টাকা জমা দিয়ে হিসাব খুললেন। মে ১২ তারিখে ব্যবসা থেকে ৫,০০০ টাকা এবং ব্যাংক থেকে ব্যক্তিগত প্রয়োজনে ৮,০০০ টাকা উত্তোলন করলেন। মে ২০ তারিখে গ্রাহক সরাসরি ব্যাংকে ১৫,০০০ টাকা জমা দিল।
**সমাধান সংক্ষেপ:**
- ব্যাংক হিসাবের মোট ডেবিট: `৫০,০০০ (নগদান) + ১৫,০০০ (দেনাদার) = ৬৫,০০০ টাকা`।
- ব্যাংক হিসাবের ক্রেডিট: `৮,০০০ টাকা (উত্তোলন হিসাব)`।
- **ব্যাংক হিসাবের ডেবিট জের:** `৬৫,০০০ - ৮,০০০ = ৫৭,০০০ টাকা`।
- **উত্তোলন হিসাবের মোট ডেবিট জের:** `৫,০০০ (নগদান) + ৮,০০০ (ব্যাংক) = ১৩,০০০ টাকা`।

---

## সৃজনশীল প্রশ্ন ০৪ (ক্রয় হিসাব ও বিক্রয় হিসাবের জের)
**নিয়ম মনে রাখো:**
1. **ক্রয় হিসাব সর্বদা ডেবিট জের নির্দেশ করে** (পণ্য উত্তোলন বা বিনামূল্যে বিতরণ ছাড়া সাধারণত ক্রেডিট হয় না)।
2. **বিক্রয় হিসাব সর্বদা ক্রেডিট জের নির্দেশ করে**।
3. সমাপনী দাখিলা ছাড়া সাধারণ অবস্থায় ক্রয় ও বিক্রয় হিসাবের ব্যালেন্স c/d ও b/d টানা হয় না, তবে শিক্ষা স্তরে অনুশীলনীর জন্য টি-ছকে সমাপনী মাসান্তে জের টানা হয়।

---

## সৃজনশীল প্রশ্ন ০৫ (খতিয়ান উদ্বৃত্ত দিয়ে রেওয়ামিল সংযোগ)
যদি কোনো প্রতিষ্ঠানের খতিয়ানের জেরগুলো নিম্নরূপ হয়:
- নগদান হিসাব: ৪০,০০০ (ডেবিট)
- মূলধন হিসাব: ১,০০,০০০ (ক্রেডিট)
- আসবাবপত্র হিসাব: ৩০,০০০ (ডেবিট)
- দেনাদার হিসাব: ২৫,০০০ (ডেবিট)
- পাওনাদার হিসাব: ১৫,০০০ (ক্রেডিট)
- বিক্রয় হিসাব: ৬০,০০০ (ক্রেডিট)
- বেতন হিসাব: ২০,০০০ (ডেবিট)
- **উভয় পাশের যোগফল সমান হবে:**
  - ডেবিট পাশ: `৪০,০০০ + ৩০,০০০ + ২৫,০০০ + ২০,০০০ = ১,১৫,০০০ টাকা`
  - ক্রেডিট পাশ: `১,০০,০০০ + ১৫,০০০ + ৬০,০০০...` (লেনদেনের ভিত্তিতে রেওয়ামিলের দুই পাশ সর্বদা সমান হয়)।

---

## 🎯 পরীক্ষার জন্য খতিয়ানের ৫টি গোল্ডেন রুলস (Exam Master Shortcuts)
1. **কলাম সংখ্যা মুখস্থ রাখুন:** টি-ছকে **৮টি** কলাম, চলমান জের ছকে **৭টি** কলাম।
2. **বিবরণের ঘরে ট্রিক:** যে হিসাবের খতিয়ান খুলছেন, বিবরণের ঘরে কখনোই সেই নাম বসবে না! সর্বদা **বিপরীত দাখিলার নাম** বসবে।
3. **তারিখের ট্রিক:** 
   - `c/d` লেখা হয় চলতি মাসের **শেষ তারিখে**।
   - `b/d` লেখা হয় পরবর্তী মাসের **১ম তারিখে**।
4. **সহকারী খতিয়ান চেনার উপায়:** কোনো সুনির্দিষ্ট ব্যক্তি বা প্রতিষ্ঠানের নামে হিসাব থাকলেই তা সহকারী খতিয়ান।
5. **জেরের প্রভাব:** সম্পদ ও ব্যয় হিসাবের উদ্বৃত্ত সর্বদা ডেবিট হবে; দায়, মালিকানা স্বত্ব ও আয় হিসাবের উদ্বৃত্ত সর্বদা ক্রেডিট হবে।$lesson$,
        6
    );

